const top_heimerdinger = {
  champion: '하이머딩거',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (Q)\'결정타\'로 이동 속도가 빨라져 순식간에 붙을 수 있어요. (Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 가렌이 다가오기 전에 포탑 피해로 견제하세요. 가렌의 (P)\'인내심\' 회복이 작동하지 않도록 포탑과 평타로 꾸준히 압박하는 것이 중요해요.', lv3: '가렌이 (Q)\'결정타\'를 써서 달려오면 (E)\'CH-2 전자폭풍 수류탄\'을 사용해 기절을 노리며 거리를 벌리세요. 가렌이 (W)\'용기\'를 사용하여 보호막을 얻었을 때는 무리하게 (W)\'마법공학 초소형 로켓\'을 쓰기보다 딜교환을 미루는 것이 좋아요. 가렌의 (E)\'심판\' 회전 범위 안으로 들어가지 않도록 주의하며 포탑을 활용해 공격하세요.', lv6: '(R)\'업그레이드!!!\'를 사용해 강화된 (E)\'CH-2 전자폭풍 수류탄\'으로 가렌을 기절시키면 킬각을 잡기 쉬워요. 하지만 가렌의 (R)\'데마시아의 정의\'는 체력이 낮을 때 매우 강력하니 체력이 빠진 상태로 방치되지 않도록 조심하세요. 가렌이 (Q)\'결정타\'로 빠르게 추격할 수 있으므로 라인을 너무 깊게 밀어두지 말고 관리하세요.', item: '첫 코어로 리안드리의 고통을 선택해 체력이 높은 가렌에게 지속적인 피해를 입히세요. 신발은 가렌의 물리 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 가렌의 (P)\'인내심\' 회복을 억제하면 킬을 따내기 쉬워요.' },
    '갱플랭크': { lv1: '갱플랭크가 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기니 거리 조절에 신경 쓰세요. (Q)\'H-28 G 진화형 포탑\'을 미리 설치해 갱플랭크가 쉽게 다가오지 못하게 압박하는 것이 좋아요. 근접 평타에 (P)\'불의 심판\' 효과가 있으니 무리하게 붙지 말고 포탑의 공격을 활용하세요.', lv3: '(E)\'화약통\' 주변에 서 있으면 폭발 피해와 둔화에 노출되니 통의 위치를 항상 확인하며 싸우세요. (W)\'괴혈병 치료\'는 군중 제어를 제거하니 귤이 준비된 동안에는 (E)\'CH-2 전자폭풍 수류탄\'에 기대지 말고 (W)\'마법공학 초소형 로켓\'으로 체력을 깎아 귤을 먼저 쓰게 유도하세요. 귤이 빠진 뒤에 수류탄을 정확히 맞히면 일방적인 딜교환이 가능해요.', lv6: '갱플랭크가 (R)\'포탄 세례\'를 사용해 둔화를 걸어오면 빠르게 범위를 벗어나세요. (R)\'업그레이드!!!\'를 사용해 강화된 수류탄으로 광범위한 기절을 노리면 포탑과 함께 빠르게 적을 처치할 수 있어요. (W)\'괴혈병 치료\'가 빠진 시점을 노려 (R)\'업그레이드!!!\' 조합으로 몰아붙이면 킬각을 잡기 편해요.', item: '판금 장화를 신어 기본 공격의 물리 피해를 줄여주세요. 리안드리의 고통을 첫 코어로 선택해 지속적인 마법 피해를 입히고 체력을 보충해 생존력을 높이세요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'괴혈병 치료\'의 체력 회복량을 줄이면 갱플랭크를 훨씬 빠르게 처치할 수 있어요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화와 견제를 넣으며 (P)\'서비스 시간\'으로 체력을 회복해요. (Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 포탑의 화력으로 상대를 압박하며 거리를 유지하세요. 술통이 굴러오는 위치를 잘 보고 피해야 해요.', lv3: '그라가스의 (E)\'몸통 박치기\'가 들어오면 에어본을 당할 수 있으니 주의하세요. (E)\'CH-2 전자폭풍 수류탄\'을 사용하여 그라가스가 돌진하기 전에 미리 둔화시키거나 기절시키는 것이 중요해요. 그라가스의 돌진기가 빠진 틈에 (W)\'마법공학 초소형 로켓\'을 맞춰서 포탑을 빠르게 충전하며 딜교하세요.', lv6: '그라가스가 (R)\'술통 폭발\'로 밀어낼 수 있으니 포탑의 위치를 신중하게 잡아야 해요. (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 넓은 범위를 공격해 그라가스의 접근을 막으며 킬각을 보세요. 그라가스가 정글러와 함께 돌진할 수 있으니 라인을 너무 깊게 밀지 않도록 관리하세요.', item: '루덴의 메아리를 첫 코어로 가서 스킬의 마법 피해를 높이세요. 신발은 그라가스의 마법 피해와 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'의 회복을 점화로 억제하고 점멸로 거리를 조절해요.' },
    '그웬': { lv1: '1~2레벨에는 (Q)\'H-28 G 진화형 포탑\'을 부지런히 설치해 최대한 멀리서 견제하며 그웬의 접근을 막아야 해요. 그웬이 (P)\'가위 난도질\'을 사용하며 붙으려 할 때는 포탑과 거리 조절을 하며 평타를 맞지 않도록 조심하세요. 초반에는 포탑을 활용해 라인을 밀어 넣으며 압박하는 것이 좋아요.', lv3: '그웬이 (E)\'돌격가위\'로 파고드는 순간에 맞춰 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절을 노리는 것이 핵심이에요. (W)\'신성한 안개\' 안의 그웬은 대상 지정 스킬로는 지정할 수 없지만 수류탄과 (W)\'마법공학 초소형 로켓\'은 위치로 던지는 스킬이라 그대로 노릴 수 있어요. 그웬의 (Q)\'싹둑싹둑!\' 원뿔 범위 밖에서 (W)\'마법공학 초소형 로켓\'을 쏘며 스킬 재사용 대기시간을 확인하세요.', lv6: '(R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 그웬을 강력하게 묶어두면 킬각을 잡을 수 있어요. 그웬이 (R)\'바느질\'로 멀리서 견제하며 들어올 수 있으니 포탑 근처에서 체력 관리를 하며 싸우세요. 상대 정글러가 근처에 있다면 포탑을 미리 배치해 퇴로를 확보하는 것이 안전해요.', item: '첫 코어 아이템으로 주문력과 마나를 제공하는 루덴의 메아리를 가고, 신발은 그웬의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 선택해요. 아이템을 빠르게 갖춰 견제력을 높이는 것이 중요해요.', spell: '점멸과 점화를 추천해요. 그웬은 (P)\'가위 난도질\'로 체력을 회복하므로 점화로 그 회복량을 줄여야 해요.' },
    '나르': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 나르가 함부로 들어오지 못하게 구역을 만드세요. (Q)\'부메랑 던지기\'의 궤적에서 벗어나며 둔화에 걸리지 않도록 주의하고 평타 교환을 피하세요. 포탑 주변에서 이동 속도가 증가하는 효과를 활용해 거리를 유지하며 천천히 압박하세요.', lv3: '나르가 (E)\'폴짝\'으로 진입한 직후에 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절을 노리세요. (W)\'슝슝\'의 추가 피해를 맞지 않도록 짧게 딜교환하고 빠지는 것이 중요해요. (W)\'마법공학 초소형 로켓\'을 적중시켜 포탑을 빠르게 충전하며 나르의 체력을 계속 깎아내세요.', lv6: '메가 나르의 (R)\'나르!\'는 벽에 부딪히면 기절하므로 벽 근처에 서지 말고 넓은 곳에서 싸우세요. (R)\'업그레이드!!!\'를 사용해 수류탄의 범위를 넓히면 메가 나르의 진입을 효과적으로 막을 수 있어요. 변신이 풀린 작은 나르는 체력이 낮으니 빠르게 집중 공격해 처치하세요.', item: '리안드리의 고통으로 체력이 높은 메가 나르에게 지속 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 라인 유지력을 높이고 정글러와 합류하여 나르를 압박하세요.' },
    '나서스': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미니언 근처에 설치해서 나서스가 (Q)\'흡수의 일격\'으로 막타를 챙기기 어렵게 압박하세요. 나서스가 다가오면 평타로 견제하며 거리를 벌리고, (P)\'영혼의 포식자\' 회복을 고려해 너무 긴 평타 싸움은 피하세요.', lv3: '나서스가 (W)\'쇠약\'을 걸고 다가오면 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시킨 뒤 빠르게 거리를 벌리세요. (W)\'마법공학 초소형 로켓\'으로 멀리서 체력을 깎으며 포탑을 충전하고, (E)\'영혼의 불길\'이 깔린 지역은 방어력이 깎이니 빠르게 벗어나세요.', lv6: '나서스가 (R)\'사막의 분노\'를 켜면 체력과 방어력이 늘어나니 무리하지 말고 거리를 유지하며 시간을 버세요. (R)\'업그레이드!!!\'를 사용하여 스킬을 강화해 진입을 막거나 체력을 깎으며 대응하세요. 라인을 계속 밀어 넣어 나서스가 (Q)\'흡수의 일격\' 중첩을 쌓을 시간을 뺏는 운영을 하세요.', item: '리안드리의 고통으로 체력이 많은 나서스에게 지속적인 피해를 입히세요. 신발은 (Q)\'흡수의 일격\' 같은 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'영혼의 포식자\'의 체력 회복 효과를 줄이고 초반에 킬각을 만들어 나서스의 성장을 늦추세요.' },
    '녹턴': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 라인 주도권을 잡아요. 녹턴이 (Q)\'황혼의 인도자\'를 타고 빠르게 접근하면 뒤로 물러나며 (W)\'마법공학 초소형 로켓\'으로 견제하세요. 포탑 근처에서 싸워야 이동 속도 이점을 챙길 수 있어요.', lv3: '녹턴이 (W)\'어둠의 장막\'으로 스킬을 막기 전에 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절을 노려야 해요. 만약 (E)\'말할 수 없는 공포\'에 연결되었다면 빠르게 사거리 밖으로 벗어나 공포를 피하세요. (W)\'마법공학 초소형 로켓\'을 맞히면 포탑이 충전되어 대응하기 편해요.', lv6: '녹턴이 (R)\'피해망상\'을 사용하면 시야가 좁아지므로 정글러의 개입을 주의해야 해요. (R)\'업그레이드!!!\'를 (E)\'CH-2 전자폭풍 수류탄\'에 사용하여 넓은 범위의 기절을 노리는 것이 좋아요. 녹턴이 돌격할 때 설치된 포탑의 화력을 활용해 대응하세요.', item: '판금 장화와 루덴의 메아리를 추천해요. 판금 장화는 녹턴의 기본 공격 피해를 줄여주고 루덴의 메아리는 스킬로 적에게 추가 피해를 입히기 좋아요.', spell: '점멸과 정화를 추천해요. (E)\'말할 수 없는 공포\'의 공포 효과는 정화로 풀 수 있어요.' },
    '다리우스': { lv1: '1~2레벨에는 (Q)\'H-28 G 진화형 포탑\'을 미리 설치하여 다리우스가 다가오지 못하게 압박하세요. 다리우스의 (Q)\'학살\' 도끼날에 맞으면 체력이 크게 회복되니 사거리를 유지하며 (W)\'마법공학 초소형 로켓\'으로 견제해요. (P)\'과다출혈\' 스택이 쌓이지 않게 포탑 근처에서 거리를 조절하는 것이 중요해요.', lv3: '다리우스가 (E)\'포획\'으로 끌어당기려 할 때 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시키거나 둔화시켜 진입을 막으세요. (W)\'마법공학 초소형 로켓\'을 적중시켜 포탑을 빠르게 충전하고 다리우스의 (Q)\'학살\' 도끼날 범위 밖에서 딜교환을 진행해요. 다리우스의 (E)\'포획\'이 빠진 타이밍에 포탑과 함께 공격하면 효율적이에요.', lv6: '(R)\'업그레이드!!!\'를 사용하여 강화된 포탑을 배치하고 다리우스의 접근을 차단하며 딜을 몰아넣으세요. 다리우스의 (R)\'녹서스의 단두대\'는 적에게 직접 뛰어올라 (P)\'과다출혈\' 중첩이 많을수록 치명적이니 포탑 뒤에 숨기보다 중첩이 쌓이기 전에 거리를 지키세요. 라인 관리를 통해 다리우스가 단독으로 진입하기 어렵게 만들며 정글러의 개입을 유도해요.', item: '판금 장화를 구매하여 다리우스의 기본 공격 피해를 줄이세요. 리안드리의 고통을 첫 코어로 올려서 적을 지속적으로 불태우며 압박하세요.', spell: '점멸과 탈진을 추천해요. 다리우스가 (E)\'포획\'으로 끌어당겨 근접전을 시작할 때 탈진을 사용하여 피해량을 줄이고 거리를 벌리세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 사용하여 멀리서 견제하며 라인을 압박해요. (Q)\'H-28 G 진화형 포탑\'을 설치하여 라이즈가 접근하기 어렵게 만들고 포탑의 사거리로 압박하세요. 라이즈가 미니언을 먹으러 올 때 포탑의 공격을 유도하며 거리를 조절해요.', lv3: '라이즈가 (E)\'주문 전이\'를 맞힌 뒤 (W)\'룬 감옥\'을 사용해 속박시키려 할 때 주의하세요. 라이즈의 (W)\'룬 감옥\'이 빠진 타이밍에 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시키면 포탑과 함께 큰 피해를 줄 수 있어요. (W)\'마법공학 초소형 로켓\'을 적중시켜 포탑을 빠르게 충전하며 딜교환을 하세요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용해 다른 곳으로 이동하려 하면 정글러의 위치를 확인하고 무리하게 따라가지 마세요. (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'은 범위가 넓어져 라이즈를 제어하기 더 쉬워져요. 라이즈가 스킬을 낭비했을 때 강화된 포탑을 깔고 강력하게 압박하세요.', item: '루덴의 메아리를 첫 코어로 가면 스킬로 적을 공격할 때 추가 피해를 줄 수 있어요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 라이즈의 (W)\'룬 감옥\'에 묶였을 때 점멸로 거리를 벌리거나 체력이 낮은 라이즈를 점화로 마무리하세요.' },
    '럼블': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 럼블이 (Q)\'화염방사기\'를 쓰며 다가오지 못하게 견제하세요. 럼블의 화염 범위 밖에서 거리를 유지하며 막타를 챙기세요. 상대가 과열되어 스킬을 못 쓰는 타이밍에 평타로 압박하세요.', lv3: '(E)\'전기 작살\'에 맞으면 둔화되고 마법 저항력이 줄어드니 주의하세요. 럼블이 (W)\'고철 방패\'를 켜고 진입할 때 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시키고 포탑을 충전하세요. (W)\'마법공학 초소형 로켓\'으로 계속해서 원거리 견제를 이어가세요.', lv6: '(R)\'이퀄라이저 미사일\'의 화염 벽 위에 있으면 둔화되어 도망치기 어려우니 즉시 옆으로 피하세요. (R)\'업그레이드!!!\'를 사용해 (E)\'CH-2 전자폭풍 수류탄\'을 강화하면 더 넓은 범위의 럼블을 기절시켜 진입을 막을 수 있어요. 럼블의 궁극기는 정글러의 호응과 잘 맞으니 라인을 밀 때 시야를 꼭 확인하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력을 보충하고 지속적인 마법 피해를 입히세요. 신발은 (E)\'전기 작살\'의 둔화 지속시간을 줄이고 마법 피해를 견디기 위해 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 럼블이 (W)\'고철 방패\'로 버티는 상황에서 점화의 추가 피해로 확실하게 처치하세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 초반 교전이 강해요. (Q)\'H-28 G 진화형 포탑\'을 미리 깔아두어 레넥톤이 접근하기 어렵게 만드세요. 레넥톤이 (E)\'자르고 토막내기\'로 들어올 때 (E)\'CH-2 전자폭풍 수류탄\'으로 거리를 벌려야 해요.', lv3: '레넥톤이 분노를 모아 (W)\'무자비한 포식자\'로 기절시키려 하면 (E)\'CH-2 전자폭풍 수류탄\'을 미리 사용하세요. 레넥톤의 (E)\'자르고 토막내기\'가 빠진 타이밍에 포탑 근처에서 (W)\'마법공학 초소형 로켓\'으로 견제하세요. 수류탄 중앙에 적을 맞춰 기절시키면 포탑과 함께 큰 피해를 줄 수 있어요.', lv6: '레넥톤이 (R)\'강신\'을 사용해 체력을 늘리고 들어오면 정면 교전은 피하세요. 레넥톤이 (E)\'자르고 토막내기\'로 진입할 때 (R)\'업그레이드!!!\'를 사용해 강화된 포탑으로 대응하세요. 라인을 밀어두고 포탑 근처에서 대기하며 레넥톤이 무리하게 들어올 때 (E)\'CH-2 전자폭풍 수류탄\'으로 끊어내야 해요.', item: '루덴의 메아리를 첫 코어로 가고 신발은 판금 장화를 선택하세요. 레넥톤의 물리 피해를 줄이기 위해서예요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\' 회복량을 감소시켜 마무리할 수 있어요.' },
    '렝가': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 수풀 근처에 설치하여 렝가의 접근을 미리 차단해요. 렝가가 (Q)\'포악함\'을 사용해 공격할 수 있으니 포탑 사거리 안에서 거리를 유지하세요. 미니언을 정리하며 포탑의 도움을 받아 압박해요.', lv3: '렝가의 (E)\'올가미 투척\'은 둔화를 걸고 야성이 가득 차면 속박까지 하니 날아오는 방향을 보고 비켜서세요. (E)\'CH-2 전자폭풍 수류탄\'으로 기절을 노리되 (W)\'전투의 포효\'는 야성이 가득 차면 군중 제어를 없애니 그때는 스킬을 아끼세요. (W)\'마법공학 초소형 로켓\'으로 포탑을 꾸준히 충전하며 견제하세요.', lv6: '렝가가 (R)\'사냥의 전율\'을 사용하여 위장 상태로 접근하면 (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 대응해요. 렝가의 도약에 대비해 라인을 당기고 정글러의 위치를 확인하며 조심하세요. 포탑을 적절히 배치해 렝가의 진입을 방해하며 전투를 이어가요.', item: '판금 장화와 루덴의 메아리를 가요. 렝가의 기본 공격 피해를 줄이고 강력한 마법 피해를 입히기 위해서예요.', spell: '점멸과 탈진을 추천해요. 렝가가 도약해 들어올 때 탈진으로 입히는 피해량을 줄이세요.' },
    '리븐': { lv1: '리븐이 (Q)\'부러진 날개\'로 빠르게 진입해 (P)\'룬 검\' 피해를 입히려 해요. (Q)\'H-28 G 진화형 포탑\'을 미리 설치하고 거리 조절을 하며 평타로 견제하세요. 리븐이 진입하는 경로에 포탑을 배치해 접근을 까다롭게 만들어요.', lv3: '리븐이 (E)\'용맹\'으로 진입해 (W)\'기 폭발\'로 기절시키려 할 때 (E)\'CH-2 전자폭풍 수류탄\'을 발밑에 던져 역으로 기절시키세요. (W)\'마법공학 초소형 로켓\'은 리븐의 (E)\'용맹\' 보호막이 사라진 뒤에 사용하는 것이 효율적이에요. 포탑 주변에서 (P)\'마법공학 전문가\' 효과로 빠르게 움직이며 리븐의 돌진 각을 피하세요.', lv6: '(R)\'추방자의 검\'을 켠 리븐은 공격 사거리가 늘어나니 평소보다 더 멀리 떨어져야 해요. (R)\'업그레이드!!!\' 이후 강화된 스킬로 리븐의 진입을 저지하거나 순간적으로 폭발적인 피해를 입히세요. 리븐의 (Q)\'부러진 날개\' 마지막 타격에 공중으로 띄워지면 스킬을 쓸 수 없으니 주의하세요.', item: '판금 장화를 신어 리븐의 (P)\'룬 검\' 평타 피해를 줄이고 리안드리의 고통을 첫 코어로 가세요. 체력이 붙어 있어 리븐의 진입 시 생존력이 올라가고 지속적인 마법 피해를 줄 수 있어요.', spell: '점멸과 순간이동을 추천해요. 리븐의 (W)\'기 폭발\'이나 (Q)\'부러진 날개\' 연계를 급히 피하기 위해 점멸이 필요하고 라인 복귀를 위해 순간이동을 사용하세요.' },
    '리산드라': { lv1: '1~2레벨에는 (Q)\'H-28 G 진화형 포탑\'을 설치해서 리산드라가 접근하지 못하게 구역을 나누세요. 리산드라의 (Q)\'얼음 파편\'은 맞은 뒤 뒤의 적까지 꿰뚫고 둔화를 거니 날아오는 방향을 보고 비켜서며 미니언을 받아먹으세요. 포탑의 화력을 이용해 초반부터 압박을 가하는 것이 좋아요.', lv3: '리산드라가 (E)\'얼음갈퀴 길\'로 들어올 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절을 시키면 딜교환에서 앞서요. 리산드라가 (W)\'서릿발\'로 속박을 걸어도 (W)\'마법공학 초소형 로켓\'은 사용할 수 있으니 침착하게 발사하세요. 리산드라의 (Q)\'얼음 파편\'을 피하면서 포탑의 지속 피해를 입히는 것이 핵심이에요.', lv6: '리산드라가 (R)\'얼음 무덤\'을 자신에게 사용해 무적 상태가 되면 공격을 멈추고 다음 행동을 기다리세요. 리산드라가 적 챔피언에게 (R)\'얼음 무덤\'을 사용하여 기절을 시키면 정글러의 개입에 주의해야 해요. (R)\'업그레이드!!!\'를 사용하여 강화된 (E)\'CH-2 전자폭풍 수류탄\'으로 리산드라의 접근을 차단하며 라인을 관리하세요.', item: '루덴의 메아리를 첫 코어로 선택해 스킬을 사용하세요. 신발은 강인함으로 리산드라의 (W)\'서릿발\'과 (R)\'얼음 무덤\'의 군중 제어 지속시간을 줄이는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 정화를 추천해요. 리산드라의 (W)\'서릿발\'이나 (R)\'얼음 무덤\'에 걸린 군중 제어를 정화로 빠르게 풀고 거리를 벌릴 수 있어요.' },
    '마스터이': { lv1: '마스터 이의 (P)\'2연속 공격\'은 초반에 위협적이지만 1~2레벨에는 몸이 약해요. (Q)\'H-28 G 진화형 포탑\'을 미리 배치하고 (W)\'마법공학 초소형 로켓\'으로 멀리서 견제하며 거리를 조절하세요. 마스터 이가 다가오려 하면 포탑의 화력을 이용해 압박하세요.', lv3: '마스터 이가 (Q)\'일격 필살\'로 들어올 때 (E)\'CH-2 전자폭풍 수류탄\'을 사용해 기절시키면 대응하기 편해요. 마스터 이가 (W)\'명상\'으로 체력을 회복할 때는 (W)\'마법공학 초소형 로켓\'을 맞춰 포탑을 빠르게 충전시키세요. (Q)\'일격 필살\'이 빠진 순간에 포탑과 함께 딜교환을 하세요.', lv6: '(R)\'최후의 전사\'를 켠 마스터 이는 둔화 면역이라 (E)\'CH-2 전자폭풍 수류탄\'의 둔화보다는 기절을 노려야 해요. (R)\'업그레이드!!!\'를 활용한 강화된 (Q)\'H-28 G 진화형 포탑\'으로 마스터 이의 진입을 막으며 싸우세요. 마스터 이가 킬을 먹고 스킬을 돌리지 못하게 라인 관리에 신경 쓰며 정글러를 부르세요.', item: '루덴의 메아리를 첫 코어로 가고 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화를 신으세요. 루덴의 메아리는 강력한 마법 피해를 제공하며 견제에 도움을 줘요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'을 사용해 체력을 회복하는 것을 막기 위해서예요.' },
    '마오카이': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 마오카이가 미니언을 먹으러 올 때 압박하세요. 마오카이가 (Q)\'덤불 주먹\'으로 밀쳐내며 다가오면 (W)\'마법공학 초소형 로켓\'으로 거리를 유지하며 괴롭히세요. (P)\'마법공학 전문가\'의 이동 속도 증가를 활용해 포탑 주변에서 안전하게 파밍하세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 돌진해 속박을 시도할 때 무리하게 맞서지 말고 뒤로 빠지세요. 마오카이의 돌진기가 빠진 것을 확인한 뒤 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시키고 포탑과 함께 공격하세요. 수풀에 설치된 (E)\'묘목 던지기\'에 갑작스럽게 폭발 피해를 입지 않도록 조심하며 싸우세요.', lv6: '마오카이가 (R)\'대자연의 마수\'를 사용하면 벽이 다가오는 방향을 보고 옆으로 비켜서서 속박을 피하세요. (R)\'업그레이드!!!\'로 강화된 (Q)\'H-28 G 진화형 포탑\'을 깔아두면 마오카이가 진입하기 까다로워져서 운영하기 편해요. (R)\'대자연의 마수\'는 먼 거리에서도 쓸 수 있으니 정글러와 함께 올 때를 대비해 시야를 확인하며 라인을 관리하세요.', item: '마법 피해가 주력인 마오카이를 상대하기 위해 헤르메스의 발걸음을 신발로 선택하세요. 첫 코어 아이템은 적을 지속적으로 태워 피해를 입히는 리안드리의 고통을 추천해요.', spell: '점멸과 탈진을 추천해요. 마오카이가 (W)\'뒤틀린 전진\'으로 돌진하며 들어올 때 탈진을 사용하면 피해량을 효과적으로 줄일 수 있어요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'는 피해를 입거나 군중 제어기에 적중당하면 사라지니 (Q)\'H-28 G 진화형 포탑\'을 설치해 먼저 공격하여 보호를 벗겨내세요. (Q)\'공허의 부름\' 투사체가 지나가는 자리는 피하며 (W)\'마법공학 초소형 로켓\'으로 견제해야 해요. 1~2레벨에는 포탑을 활용해 말자하를 압박하세요.', lv3: '말자하가 (E)\'재앙의 환상\'을 사용하면 다른 스킬로 지속시간이 초기화되니 거리를 조절하며 피해를 줄이세요. (E)\'CH-2 전자폭풍 수류탄\'을 적중시켜 말자하를 기절시키면 근처 (Q)\'H-28 G 진화형 포탑\'이 즉시 충전되어 큰 피해를 줄 수 있어요. (W)\'공허의 무리\'가 소환되면 포탑으로 빠르게 정리하세요.', lv6: '말자하의 (R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니 매우 조심해야 해요. (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 말자하를 기절시켜 진입을 늦추거나 포탑을 강화해 대응하세요. 말자하가 궁극기를 쓰기 전에 라인을 밀어두고 정글러의 개입에 대비하세요.', item: '첫 코어로 루덴의 메아리를 선택해 주문력과 마나를 확보하세요. 신발은 마법 저항력을 주고 (Q)\'공허의 부름\' 침묵 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\' 제압 중에는 점멸도 정화도 쓸 수 없으니 제압에 걸리기 전에 거리를 조절하고 점화로 마무리하세요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'을 사용해 이동 속도를 훔치는데 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (Q)\'H-28 G 진화형 포탑\'을 미리 설치하고 포탑 근처에서 거리 조절을 하며 압박하세요. (P)\'화강암 방패\'가 재생성되기 전에 계속해서 공격을 적중시켜 보호막을 지워야 해요.', lv3: '말파이트가 (E)\'지면 강타\'로 공격 속도를 낮추려 하면 (E)\'CH-2 전자폭풍 수류탄\'으로 기절시켜 흐름을 끊으세요. (W)\'천둥소리\'의 물리 피해를 주는 기본 공격 범위에 오래 머물지 말고 (W)\'마법공학 초소형 로켓\'으로 멀리서 포탑을 충전하며 견제하세요. 상대의 돌진 수단이 없으니 포탑 주변에서 짧은 딜교환을 반복하며 체력을 깎으세요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 상태로 돌진해 공중에 띄우므로 맞으면 스킬을 쓸 수 없으니 주의하세요. 저지 불가 돌진은 군중 제어로 끊을 수 없으니 (R)\'업그레이드!!!\'를 쓴 (E)\'CH-2 전자폭풍 수류탄\'은 말파이트가 돌진하기 전에 던져 기절을 노리세요. 라인을 빠르게 밀어 상대가 (R)\'멈출 수 없는 힘\'으로 정글러와 함께 덮치는 각을 주지 마세요.', item: '리안드리의 고통을 가서 체력이 높은 말파이트에게 지속적인 화상 피해를 입히세요. 신발은 (Q)\'지진의 파편\'과 (E)\'지면 강타\'의 마법 피해를 줄이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 말파이트의 (R)\'멈출 수 없는 힘\' 돌진을 피하거나 빠르게 합류하여 포탑 진형을 구축하는 것이 중요해요.' },
    '모데카이저': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 모데카이저가 다가오지 못하게 압박하세요. 모데카이저의 (Q)\'말살\' 범위 밖에서 포탑 피해를 누적시키고, (P)\'암흑 탄생\' 오라가 켜지기 전에 거리를 벌려야 해요. 첫 웨이브는 포탑 주변의 이동 속도 증가 효과를 활용해 무빙하며 견제하세요.', lv3: '(E)\'죽음의 손아귀\'에 끌려오면 바로 (E)\'CH-2 전자폭풍 수류탄\'을 발밑에 던져 기절시키고 빠져나가세요. (W)\'마법공학 초소형 로켓\'을 적중시켜 포탑을 충전시키면 모데카이저가 (W)\'불멸\' 보호막을 켜기 전에 큰 피해를 줄 수 있어요. 끌어당기기 스킬이 빠진 상태에서는 포탑과 함께 공격하며 거리를 유지하세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 수은 장식띠로도 풀 수 없고 순간이동으로 빠져나갈 수 없으니 진입 전에 차단해야 해요. (R)\'업그레이드!!!\'를 사용해 강화된 (E)\'CH-2 전자폭풍 수류탄\'으로 접근하는 모데카이저를 먼저 기절시키세요. 포탑을 최대한 많이 배치해 두고 정글러가 올 때까지 라인을 당겨서 유지하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력을 높이고 지속적인 화상 피해를 입히세요. 신발은 모데카이저의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'의 체력 회복 효과를 점화로 줄여야 킬각을 잡기 편해요.' },
    '문도박사': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치해 문도 박사의 접근을 막으면서 (W)\'마법공학 초소형 로켓\'으로 멀리서 견제하세요. 문도 박사의 (Q)\'오염된 뼈톱\'은 처음 맞는 대상에게 적중하므로 미니언 뒤에 서서 피해를 피하는 것이 중요해요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 사용하면 피해를 저장했다가 회복하니 근접해서 싸우지 마세요. (E)\'CH-2 전자폭풍 수류탄\'으로 문도 박사를 기절시키거나 둔화시킨 뒤 (Q)\'H-28 G 진화형 포탑\'의 화력을 집중하세요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 쓰면 체력이 빠르게 차오르니 무리하게 추격하지 마세요. (R)\'업그레이드!!!\'를 사용하여 강화된 포탑이나 로켓으로 문도 박사와 거리를 유지하며 라인을 관리하세요. 궁극기가 빠진 시점에 정글러와 함께 압박하는 것이 좋아요.', item: '리안드리의 고통을 첫 코어로 올려 문도 박사를 지속적으로 괴롭히세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 효과로 문도 박사의 (R)\'최대 투여량\' 회복을 줄여야 킬을 낼 수 있어요.' },
    '바루스': { lv1: '바루스가 (Q)\'꿰뚫는 화살\'을 조준하면 옆으로 움직여 피해를 피하며 (Q)\'H-28 G 진화형 포탑\'을 설치하세요. 미니언 근처에 포탑을 세워 바루스가 다가오기 어렵게 만들고 웨이브를 관리해요. 초반에는 무리하게 맞붙기보다 포탑의 도움을 받아 거리를 유지하며 버티세요.', lv3: '바루스가 (W)\'역병 화살\'을 묻힌 뒤 (E)\'퍼붓는 화살\'로 폭발시키는 것을 조심해야 해요. (E)\'CH-2 전자폭풍 수류탄\'을 적중시켜 기절시킨 뒤 포탑과 함께 (W)\'마법공학 초소형 로켓\'으로 딜교환을 시도하세요. 바루스가 (Q)\'꿰뚫는 화살\'을 충전하느라 느려지는 순간을 이용해 스킬을 맞히면 좋아요.', lv6: '바루스의 (R)\'부패의 사슬\'을 맞으면 이동이 막히니 조심해서 피해야 해요. (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'은 범위가 커지니 이를 활용해 바루스를 기절시키고 킬각을 잡으세요. 바루스가 궁극기를 빗맞히면 포탑을 배치해 압박하며 정글러와 함께 움직이세요.', item: '루덴의 메아리를 첫 코어로 올려서 포탑과 함께 강력한 마법 피해를 입히세요. 신발은 바루스의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점멸로 거리를 조절하고 점화로 바루스의 체력을 깎으며 킬을 노리세요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 조절하며 (W)\'은화살\'의 고정 피해를 입히려 하니 정면 평타 교환은 피하세요. (Q)\'H-28 G 진화형 포탑\'을 설치해 베인이 쉽게 들어오지 못하는 영역을 만들고, 멀리서 (W)\'마법공학 초소형 로켓\'으로 툭툭 쳐서 체력을 깎으세요. 포탑 주변에서 (P)\'마법공학 전문가\' 효과로 이동 속도를 얻어 베인의 거리 조절에 대응하세요.', lv3: '베인의 (E)\'선고\'는 지형에 부딪히면 기절시키니 벽 근처에 서지 말고 넓은 공간에서 싸우세요. 베인이 (Q)\'구르기\'로 진입하는 순간 (E)\'CH-2 전자폭풍 수류탄\'을 정확히 던져 기절시킨 뒤 포탑 공격을 집중하세요. (E)\'CH-2 전자폭풍 수류탄\'에 맞은 적은 근처 포탑을 최대로 충전시키니 짧고 강하게 딜교환을 마쳐야 해요.', lv6: '베인이 (R)\'결전의 시간\'을 사용해 투명 상태로 움직이면 공격하기 어려우니 무리하게 쫓지 마세요. (R)\'업그레이드!!!\'를 사용하여 강화된 수류탄을 던지면 더 넓은 범위의 적을 기절시킬 수 있어 투명 상태에서 나타나는 베인을 잡기 편해요. 라인을 밀어두고 포탑 근처에서 대기하며 정글러와 함께 덮치는 구도를 만드세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화는 베인의 기본 공격 피해를 줄여주고, 리안드리의 고통은 주문력과 체력을 제공하며 적을 불태워 지속 피해를 줘요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (E)\'CH-2 전자폭풍 수류탄\'의 적중률을 높이고, 순간이동으로 라인 복귀를 빠르게 하여 포탑을 다시 설치하세요.' },
    '볼리베어': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 볼리베어가 쉽게 다가오지 못하게 하세요. 볼리베어가 (Q)\'번개 강타\'로 빠르게 달려들어 기절시키려 할 때 거리 조절을 하며 포탑 화력으로 대응하세요. (W)\'마법공학 초소형 로켓\'으로 멀리서 견제하며 체력을 깎아두는 것이 좋아요.', lv3: '볼리베어가 (W)\'광란의 상처\' 표식을 남기고 체력을 회복하니 표식이 붙었다면 교환을 길게 끌지 마세요. (E)\'천공 분열\' 범위 안에서는 볼리베어가 보호막을 얻으니 그 구역 밖에서 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시키세요. 기절 후에는 포탑들이 최대 충전되어 강력한 피해를 입힐 수 있어요.', lv6: '(R)\'폭풍을 부르는 자\'로 도약하면 착지한 곳 근처의 아군 포탑 구조물이 일시적으로 비활성화되니 구조물만 믿고 너무 가까이 서 있지 마세요. 볼리베어가 진입하는 타이밍에 (R)\'업그레이드!!!\'를 쓴 (E)\'CH-2 전자폭풍 수류탄\'으로 넓은 범위에 기절을 걸어 밀어내세요. 정글 개입이 올 때 (Q)\'H-28 G 진화형 포탑\' 구역으로 유인해 함께 공격하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 많은 볼리베어에게 지속 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 적당해요.', spell: '점멸과 점화를 추천해요. (W)\'광란의 상처\'로 회복하는 볼리베어의 체력 회복량을 점화로 줄여서 마무리하세요.' },
    '블라디미르': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 블라디미르가 다가오지 못하게 구역을 설정하세요. (Q)\'수혈\'은 대상을 직접 지정하는 스킬이라 미니언 뒤에 숨어도 피할 수 없으니 항상 주의하세요. 포탑의 공격을 이용해 상대의 체력을 조금씩 깎으며 거리를 유지하세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'으로 기절을 맞히면 근처 포탑이 즉시 충전되어 매우 강한 피해를 줄 수 있어요. 블라디미르가 (W)\'피의 웅덩이\'로 변해 있는 동안에는 공격 대상이 되지 않으니 스킬을 아꼈다가 풀린 뒤에 쓰세요. (E)\'선혈의 파도\' 범위에서 빠르게 벗어나며 딜교환을 이어가세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나고 나중에 추가 피해까지 입으니 감염된 즉시 뒤로 물러나세요. (R)\'업그레이드!!!\'를 사용해 강화된 수류탄으로 넓은 범위의 기절을 시켜 포탑과 함께 빠르게 제압하세요. 블라디미르가 (W)\'피의 웅덩이\'를 쓴 직후가 가장 취약한 타이밍이니 이때 스킬을 집중하세요.', item: '모렐로노미콘을 첫 코어로 선택해 (Q)\'수혈\'로 회복하는 양을 줄이세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 블라디미르가 (Q)\'수혈\'로 체력을 계속 회복하므로 점화의 치유 감소 효과가 꼭 필요해요.' },
    '뽀삐': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 압박하며 뽀삐가 다가오지 못하게 하세요. 뽀삐가 (Q)\'망치 강타\'를 사용해 만든 둔화 지대 위에 서 있으면 폭발 피해를 입으니 빠르게 자리를 옮겨야 해요. (W)\'마법공학 초소형 로켓\'을 멀리서 날리며 포탑 근처에서 거리를 유지하세요.', lv3: '뽀삐가 (E)\'용감한 돌진\'으로 벽에 부딪히면 기절하니 벽 근처에서는 최대한 거리를 벌리세요. 뽀삐의 (W)\'굳건한 태세\'는 돌진하는 적을 막고 체력이 낮아질수록 방어력과 마법 저항력이 커지니 무리하게 몰아붙이지 말고 (E)\'CH-2 전자폭풍 수류탄\'을 맞출 틈을 보세요. 포탑의 사거리 안에서 딜교환을 하며 뽀삐의 접근을 막는 것이 좋아요.', lv6: '(R)\'업그레이드!!!\'를 (E)\'CH-2 전자폭풍 수류탄\'에 사용해 넓은 범위의 기절을 맞히면 킬을 노리기 쉬워요. 뽀삐가 (R)\'수호자의 심판\'으로 나를 멀리 날려 보내려고 하면 충전하는 동안 범위 밖으로 벗어나세요. 포탑을 세워 라인을 빠르게 밀어 넣으며 뽀삐의 압박을 관리하고 정글러의 개입에 대비하세요.', item: '뽀삐의 물리 피해를 줄이기 위해 판금 장화를 선택하세요. 첫 코어 아이템으로는 마법 피해를 높여주는 루덴의 메아리를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 뽀삐의 체력을 깎으며 킬각을 잡기에 좋아요.' },
    '사이온': { lv1: '1~2레벨 구간에는 (Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 사이온이 함부로 다가오지 못하게 하세요. (E)\'학살자의 포효\'는 미니언을 밀어내며 관통해 오니 미니언과 일직선으로 서지 말고 옆으로 움직이며 피해를 피하세요.', lv3: '사이온이 (Q)\'대량 학살 강타\'를 충전하면 기절당할 수 있으니 즉시 옆으로 피하세요. (E)\'CH-2 전자폭풍 수류탄\'을 정확히 맞혀 기절시키고 포탑을 최대로 충전해 큰 피해를 입히세요. (W)\'영혼의 용광로\' 보호막이 켜진 동안에는 딜교환을 멈추고 보호막이 터진 뒤에 공격하세요.', lv6: '(R)\'멈출 수 없는 맹공\'으로 돌진해올 때는 당황하지 말고 옆으로 비켜서 충돌을 피하세요. (R)\'업그레이드!!!\'를 사용해 더 강력한 포탑을 배치해서 사이온의 체력을 빠르게 깎으세요. 사이온이 죽은 뒤 (P)\'영광스러운 죽음\'으로 되살아나 공격하니 즉시 거리를 벌려 안전하게 대처하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 사이온에게 지속적인 피해를 입히세요. 신발은 기절과 둔화 시간을 줄여주는 헤르메스의 발걸음이 적절해요.', spell: '점멸과 순간이동을 추천해요. 사이온이 라인을 밀어내는 능력이 좋으므로 순간이동으로 복귀해 손해를 최소화하세요.' },
    '사일러스': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치하여 사일러스가 다가오기 어려운 환경을 만드세요. (W)\'마법공학 초소형 로켓\'으로 견제하며 사일러스의 (Q)\'사슬 후려치기\'가 빗나가도록 거리를 조절해요. 사일러스가 (P)\'페트리사이트 폭발\'을 위해 붙으려 하면 포탑의 공격을 활용해 거리를 벌리세요.', lv3: '사일러스가 (E)\'도주 / 억압\'으로 진입하면 (E)\'CH-2 전자폭풍 수류탄\'을 적중시켜 기절시키거나 둔화시켜야 해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하기 전에 (W)\'마법공학 초소형 로켓\'으로 먼저 피해를 입히세요. 사일러스의 (Q)\'사슬 후려치기\'가 빠진 타이밍을 노려 포탑 근처에서 딜교환을 하세요.', lv6: '사일러스가 (R)\'강탈\'을 사용하여 (R)\'업그레이드!!!\'를 훔쳐 가면 매우 위협적이니 주의하세요. (R)\'업그레이드!!!\'를 활용한 (E)\'CH-2 전자폭풍 수류탄\'으로 사일러스를 빠르게 제압하는 것이 중요해요. 사일러스가 (W)\'국왕시해자\'로 버티지 못하게 포탑을 계속 유지하며 압박을 이어가세요.', item: '루덴의 메아리를 첫 코어로 선택해 스킬 피해를 높이세요. 신발은 사일러스의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (W)\'국왕시해자\'로 회복하는 사일러스를 점화의 치유 감소로 억제하세요.' },
    '세주아니': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치하고 거리 조절을 하며 견제해요. 상대가 (Q)\'혹한의 맹습\'으로 진입하려 하면 뒤로 물러나며 포탑 피해를 입히세요. 첫 웨이브부터 지속적으로 평타와 포탑으로 압박을 줘야 해요.', lv3: '(W)\'마법공학 초소형 로켓\'으로 멀리서 체력을 깎고 (E)\'CH-2 전자폭풍 수류탄\'으로 진입을 차단하세요. (E)\'만년 서리\'는 서리가 최대로 중첩된 대상만 기절시키니 세주아니의 평타와 (W)\'혹한의 서릿발\'로 중첩이 쌓이기 전에 짧게 교환하고 빠지세요. 포탑 근처에서 싸우며 거리 조절에 집중하세요.', lv6: '(R)\'빙하 감옥\'의 긴 사거리와 기절에 주의하며 무리한 진입을 삼가세요. (R)\'업그레이드!!!\' 이후 강화된 수류탄으로 상대의 진입을 기절시키거나 포탑을 추가해 딜교환을 유도해요. 정글 개입 시 상대의 CC 연계가 강력하므로 라인을 당겨 관리하세요.', item: '리안드리의 고통과 헤르메스의 발걸음을 추천해요. 높은 체력을 가진 상대에게 지속 피해를 주고 강인함으로 기절 지속시간을 줄여야 해요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀를 빠르게 하고 점멸로 세주아니의 (Q)\'혹한의 맹습\' 돌진을 피하세요.' },
    '세트': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치하여 세트가 쉽게 접근하지 못하도록 영역을 만드세요. 세트가 (Q)\'주먹다짐\'을 사용하며 달려들면 (W)\'마법공학 초소형 로켓\'으로 거리를 유지하며 계속 견제해요. 포탑이 쌓이는 동안 세트의 돌진을 경계하며 안전하게 파밍하는 것이 중요해요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'을 세트의 발밑에 던져서 기절시키거나 둔화를 거는 것이 중요해요. 세트가 (E)\'안면 강타\'로 끌어당기려 할 때는 미니언과 거리를 조절하며 스킬을 피해야 해요. 세트가 피해를 쌓아 (W)\'강펀치\' 보호막을 두껍게 만들기 전에 (W)\'마법공학 초소형 로켓\'으로 체력을 깎으세요.', lv6: '(R)\'업그레이드!!!\'로 강화된 (E)\'CH-2 전자폭풍 수류탄\'을 사용하면 세트를 더 쉽게 묶고 킬을 노릴 수 있어요. 세트가 (R)\'대미 장식\'으로 나를 붙잡아 공중으로 내리꽂을 수 있으니 포탑을 방패 삼아 싸우세요. 세트가 궁극기를 쓰기 전에 포탑을 미리 배치하여 라인 주도권을 유지하며 정글러의 도움을 기다려요.', item: '루덴의 메아리를 첫 코어로 가서 마나와 스킬 피해를 확보하세요. 신발은 세트의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 세트가 (P)\'투기장의 투지\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 입히고 스킬 사용 시 (P)\'기 보호막\'을 얻어요. (Q)\'H-28 G 진화형 포탑\'을 설치해 거리를 유지하며 쉔의 접근을 방해하고 (W)\'마법공학 초소형 로켓\'으로 견제하세요. 쉔이 기의 검을 사용할 때는 직선 경로를 피해 포탑 근처에서 버텨야 해요.', lv3: '쉔이 (E)\'그림자 돌진\'으로 들어오면 도발에 걸려 스킬을 쓸 수 없으니 주의하세요. 쉔의 돌진 전에 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절을 맞히면 교환을 원활하게 할 수 있어요. 쉔이 (W)\'의지의 결계\'를 켜면 포탑의 공격이 차단될 수 있으니 결계가 사라진 뒤에 다시 압박하세요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용해 다른 라인으로 이동하면 라인을 빠르게 밀어 압박하세요. 쉔이 진입할 때는 (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 더 넓은 범위를 기절시켜 대응하세요. 쉔의 궁극기가 빠진 뒤에는 포탑과 (W)\'마법공학 초소형 로켓\'을 활용해 킬각을 노려보세요.', item: '리안드리의 고통을 첫 코어로 가서 지속적인 피해를 입히세요. 신발은 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 쉔이 (E)\'그림자 돌진\'으로 들어올 때 점화를 사용하여 마무리 피해를 입히세요.' },
    '쉬바나': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치하여 쉬바나가 다가오는 길목을 차단해요. 쉬바나가 (Q)\'잉걸불 일격\'을 사용하며 접근할 때 포탑의 사격으로 거리를 유지하며 견제하세요. 포탑 주변의 이동 속도 증가 효과를 활용해 위치를 잡는 것이 중요해요.', lv3: '쉬바나가 (W)\'지옥불 방패\'를 켜고 들어올 때 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절을 노려요. 기절에 성공하면 (W)\'마법공학 초소형 로켓\'을 맞춰 포탑을 빠르게 충전시키고 압박하세요. 상대의 (E)\'용암 분출\'이 닿지 않도록 포탑 사이의 간격을 조절하며 대응해요.', lv6: '쉬바나가 (R)\'용의 강림\'으로 날아올 때는 저지 불가 상태이므로 미리 거리를 두어야 해요. (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 넓은 범위를 타격해 접근을 방해하세요. 용 형상일 때 (W)\'지옥불 방패\'로 체력을 회복하며 버티므로 무리한 싸움보다는 포탑을 이용해 라인을 관리하며 정글러의 도움을 기다려요.', item: '리안드리의 고통과 헤르메스의 발걸음을 구매해요. 리안드리의 고통으로 체력이 높은 상대를 괴롭히고 헤르메스의 발걸음으로 마법 저항력을 확보해요.', spell: '점멸과 점화를 선택해요. 점멸로 위험한 상황에서 벗어나고 점화로 용 형상일 때 (W)\'지옥불 방패\'를 통한 체력 회복 효과를 억제하며 마무리하세요.' },
    '스웨인': { lv1: '1~2레벨 구간에는 (Q)\'H-28 G 진화형 포탑\'을 설치해서 스웨인의 접근을 막으며 견제하세요. 스웨인이 (Q)\'죽음의 손길\'로 체력을 깎으려 할 때 포탑 사거리를 활용해 거리를 유지하는 것이 중요해요. 초반에 포탑 화력으로 스웨인의 체력을 미리 낮춰두어야 해요.', lv3: '(E)\'속박명령\'의 파동을 보고 옆으로 비켜서서 속박을 피하세요. 스웨인이 (Q)\'죽음의 손길\'을 맞히려고 다가오면 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시키거나 진입을 늦추는 것이 좋아요. (E)\'CH-2 전자폭풍 수류탄\'을 맞히면 포탑이 최대로 충전되어 화력을 집중하기 편해요.', lv6: '(R)\'악의 승천\'을 켜면 주변 체력을 흡수하므로 포탑과 함께 거리를 두며 싸우세요. (R)\'업그레이드!!!\'를 사용하여 강화된 스킬로 스웨인의 진입을 방해하며 화력을 집중하세요. 스웨인이 변신했을 때 무리하게 싸우기보다는 라인을 밀어 넣으며 정글러의 도움을 기다리세요.', item: '스웨인의 마법 피해에 대응하기 위해 헤르메스의 발걸음과 리안드리의 고통을 가세요. 리안드리의 고통은 스웨인에게 지속적인 피해를 입히기 좋아요.', spell: '점멸과 점화를 추천해요. 스웨인이 (R)\'악의 승천\'으로 체력을 회복하는 것을 점화로 억제해야 해요.' },
    '스카너': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 스카너가 다가오기 힘들게 만들어요. (W)\'마법공학 초소형 로켓\'으로 멀리서 포탑 충전을 도와주며 견제해요. 스카너가 (Q)\'부서진 대지/지반 돌출\'을 사용하며 다가오면 거리를 유지하며 대응해요.', lv3: '스카너가 (E)\'이쉬탈의 격돌\'로 들어올 때 (E)\'CH-2 전자폭풍 수류탄\'을 던져 진입을 방해해요. (W)\'마법공학 초소형 로켓\'을 맞춰 포탑의 공격을 준비해요. 스카너의 (Q)\'부서진 대지/지반 돌출\' 투사체를 조심하며 거리를 유지해요.', lv6: '(R)\'업그레이드!!!\'를 통해 강화된 (E)\'CH-2 전자폭풍 수류탄\'으로 스카너의 접근을 막아요. 스카너의 (R)\'꿰뚫기\' 제압에 걸리지 않도록 주의하며 라인을 포탑으로 압박해요. 정글러가 올 경우 포탑이 설치된 안전한 위치를 확보해요.', item: '루덴의 메아리와 헤르메스의 발걸음을 가요. 루덴의 메아리로 피해를 높이고 헤르메스의 발걸음으로 스카너의 군중 제어 지속시간을 줄여요.', spell: '점멸과 탈진을 추천해요. 스카너가 진입했을 때 탈진으로 입히는 피해량을 줄이세요.' },
    '신지드': { lv1: '신지드가 (Q)\'맹독의 자취\'를 켜고 다가올 때 (Q)\'H-28 G 진화형 포탑\'을 미리 설치해 접근을 늦추세요. 독구름 속에 들어가면 피해를 입으니 거리 조절을 하며 포탑 주변의 이동 속도 증가 효과를 활용해 피하세요. 무리하게 추격하지 말고 포탑의 공격으로 신지드의 체력을 깎으세요.', lv3: '신지드가 (W)\'초강력 접착제\'를 던져 이동을 방해하려 할 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시켜 흐름을 끊으세요. (E)\'던져넘기기\'에 맞으면 신지드 뒤로 던져지니 당황하지 말고 (W)\'마법공학 초소형 로켓\'으로 즉시 피해를 입히세요. 접착제 위에 떨어져 속박되기 전에 빠르게 위치를 잡는 것이 중요해요.', lv6: '신지드가 (R)\'광기의 물약\'을 마시고 빠르게 달려오면 (R)\'업그레이드!!!\'를 사용해 강화된 수류탄으로 광역 기절을 시키세요. 신지드가 라인을 밀어내려 하면 포탑을 촘촘히 배치해 정글러가 올 때까지 버티는 것이 좋아요. 궁극기 사용 후에는 신지드의 진입 경로에 포탑을 집중적으로 설치해 대응하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 높은 신지드에게 지속적인 피해를 주세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 신지드의 체력 재생력을 억제하고 킬각을 잡을 때 점화의 추가 피해가 유용해요.' },
    '신짜오': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치하여 신짜오의 접근을 방해해요. (W)\'마법공학 초소형 로켓\'으로 꾸준히 견제하면서 신짜오가 (Q)\'삼조격\'을 사용해 붙지 못하도록 거리를 유지하세요.', lv3: '신짜오가 (E)\'무쌍돌격\'으로 진입할 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞혀 기절을 유도해야 해요. 신짜오의 (W)\'풍전참뢰\'에 맞으면 둔화되어 포탑에서 도망치기 힘들어지니 주의하세요.', lv6: '신짜오가 (R)\'현월수호\'를 쓰면 도전 받지 않은 적을 밀쳐내고 창이 닿는 거리 밖에서 오는 공격에는 피해를 입지 않으니 그동안은 무리하게 교환하지 마세요. 신짜오가 진입하기 전에 (R)\'업그레이드!!!\'를 쓴 (E)\'CH-2 전자폭풍 수류탄\'으로 기절을 노리세요. (Q)\'H-28 G 진화형 포탑\'으로 들어오는 타이밍에 맞춰 피해를 입히는 것이 중요해요.', item: '판금 장화와 리안드리의 고통을 구매해요. 신짜오의 물리 피해를 줄이기 위해 판금 장화를 가고 지속적인 피해를 위해 리안드리의 고통을 선택해요.', spell: '점멸과 탈진을 사용해요. 신짜오가 (E)\'무쌍돌격\'으로 진입할 때 탈진을 사용하여 피해량을 줄여요.' },
    '아이번': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 아이번이 다가오지 못하게 압박하세요. 아이번의 (Q)\'덩굴뿌리\'는 처음으로 적중한 대상만 속박하므로 미니언 뒤에 서서 공격을 피하는 것이 중요해요. (Q)\'덩굴뿌리\'는 사거리가 기니 미니언이 없는 곳에 혼자 서 있지 말고 포탑 근처에서 거리를 유지하세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'으로 아이번을 기절시켜 포탑을 최대로 충전하고 강력한 피해를 입히세요. 아이번이 (E)\'보호의 씨앗\'으로 보호막을 씌우기 전에 (W)\'마법공학 초소형 로켓\'을 맞춰 체력을 깎는 것이 좋아요. 상대의 (Q)\'덩굴뿌리\'가 빠진 타이밍에 포탑 주변에서 공격적인 딜교환을 시도하세요.', lv6: '아이번이 (R)\'데이지!\'를 소환하면 데이지의 공격에 공중으로 띄워지지 않도록 거리를 벌리세요. 아이번이 다가오는 타이밍에 (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 아이번을 기절시켜 진입을 막으세요. 포탑을 전략적으로 배치해 정글러의 개입을 차단하고 라인 주도권을 유지하세요.', item: '루덴의 메아리와 헤르메스의 발걸음을 추천해요. 루덴의 메아리로 스킬 피해를 높이고 헤르메스의 발걸음의 강인함으로 (Q)\'덩굴뿌리\' 속박 시간을 줄이세요.', spell: '점멸과 점화를 추천해요. 점멸로 (Q)\'덩굴뿌리\'를 피하며 거리를 조절하고 점화로 체력이 낮은 아이번을 마무리하세요.' },
    '아지르': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 아지르가 다가오기 힘들게 만드세요. 아지르가 (W)\'일어나라!\'로 멀리서 공격할 때 포탑의 도움을 받아 거리를 조절하며 견제해요.', lv3: '아지르의 (Q)\'사막의 맹습\'을 피하며 거리를 유지하세요. (E)\'CH-2 전자폭풍 수류탄\'을 적중시켜 기절을 시킨 뒤 (W)\'마법공학 초소형 로켓\'으로 강하게 압박해요.', lv6: '(R)\'업그레이드!!!\'를 사용하여 강화된 수류탄으로 아지르를 압박하며 킬을 노려보세요. 아지르가 (R)\'황제의 진영\'으로 밀어내며 거리를 벌리면 포탑 근처에서 라인을 관리하며 정글러를 불러요.', item: '헤르메스의 발걸음과 리안드리의 고통을 선택해요. 마법 피해에 저항하고 지속적인 마법 피해를 입히기 위해서예요.', spell: '점멸과 점화를 사용해요. 아지르의 진입에 대응하고 부족한 피해를 보충하기 위해서예요.' },
    '아칼리': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치하여 아칼리가 쉽게 다가오지 못하게 하세요. 아칼리의 (Q)\'오연투척검\' 견제에 대비하고 (P)\'암살자의 표식\' 경계를 넘으며 들어오는 강화 평타를 조심하며 거리를 조절하세요. 포탑을 활용해 초반부터 압박을 유지하세요.', lv3: '아칼리가 (E)\'표창곡예\'로 표식을 남기고 돌진할 때 (E)\'CH-2 전자폭풍 수류탄\'을 사용하여 흐름을 끊어주세요. (W)\'황혼의 장막\' 안에서는 아칼리를 지정할 수 없으니 (W)\'마법공학 초소형 로켓\'처럼 투사체 스킬로 대응하세요. 아칼리의 (Q)\'오연투척검\'이 빠진 타이밍에 딜교환을 시도하세요.', lv6: '아칼리가 (R)\'무결처형\'의 두 번째 돌진을 사용하기 전에 (R)\'업그레이드!!!\'를 사용하여 (E)\'CH-2 전자폭풍 수류탄\'의 기절을 노려보세요. 연막 속의 아칼리를 쫓기보다는 포탑을 활용해 라인을 밀어 넣으며 정글의 위치를 확인하세요. 아칼리의 진입 경로를 미리 예측하며 움직이는 것이 중요해요.', item: '루덴의 메아리를 구매하여 포탑과 함께 강력한 마법 피해를 입히세요. 신발은 아칼리의 마법 피해와 군중 제어에 대비해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 탈진을 추천해요. 탈진은 아칼리가 (R)\'무결처형\'으로 진입했을 때 입히는 피해를 줄여주어 생존에 큰 도움이 돼요.' },
    '아크샨': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치하여 아크샨이 함부로 다가오지 못하게 하세요. 아크샨의 (Q)\'복수의 부메랑\' 사거리 안에서 정면으로 딜교환하기보다 포탑의 지원을 받으며 (W)\'마법공학 초소형 로켓\'으로 견제하는 것이 좋아요. (P)\'마법공학 전문가\' 패시브를 활용해 포탑 주변에서 이동 속도를 높이며 거리를 조절하세요.', lv3: '아크샨이 (E)\'영웅의 비상\'으로 진입할 때 (E)\'CH-2 전자폭풍 수류탄\'을 사용해 기절시키거나 둔화시켜야 해요. 아크샨이 (Q)\'복수의 부메랑\'을 맞히고 들어오려 할 때 포탑과 함께 (W)\'마법공학 초소형 로켓\'을 발사하며 대응하세요. (Q)\'H-28 G 진화형 포탑\'을 미리 깔아두어 아크샨의 접근을 억제하는 것이 중요해요.', lv6: '(R)\'업그레이드!!!\'를 사용해 강화된 (E)\'CH-2 전자폭풍 수류탄\'으로 아크샨의 움직임을 억제하며 압박하세요. 아크샨의 (R)\'인과응보\'는 체력이 낮을 때 위협적이니 항상 체력 관리에 신경을 써야 해요. 포탑을 적절히 배치해 라인을 관리하며 아크샨이 (E)\'영웅의 비상\'으로 도망치거나 진입하지 못하게 만드세요.', item: '판금 장화와 루덴의 메아리를 선택하세요. 아크샨의 기본 공격 피해를 줄이고 강력한 마법 피해를 입히기 위해서예요.', spell: '점멸과 탈진을 추천해요. 아크샨이 (E)\'영웅의 비상\'으로 들어올 때 입히는 피해량을 감소시키기 위해서예요.' },
    '아트록스': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치해 아트록스가 (Q)\'다르킨의 검\'을 휘두르며 접근하기 어렵게 만드세요. 아트록스가 (Q)\'다르킨의 검\'을 사용해 다가오면 (W)\'마법공학 초소형 로켓\'으로 거리를 벌리며 견제해요. 1~2레벨 구간에는 포탑의 화력을 이용해 미니언을 챙기며 거리 조절을 잘해야 해요.', lv3: '아트록스가 (E)\'파멸의 돌진\'으로 들어오려 하거나 (W)\'지옥사슬\'을 사용하면 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시키세요. 아트록스의 (Q)\'다르킨의 검\'이 빠진 직후에 (W)\'마법공학 초소형 로켓\'과 설치한 포탑으로 딜교환을 해요. (W)\'지옥사슬\'의 중앙으로 끌려가지 않도록 사슬 범위 밖으로 빠르게 움직이는 것이 중요해요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 사용하면 공격력과 체력 회복량이 늘어나니 맞대결을 피하세요. (R)\'업그레이드!!!\'를 사용해 강화된 (E)\'CH-2 전자폭풍 수류탄\'을 맞히면 아트록스의 진입을 효과적으로 저지할 수 있어요. (R)\'업그레이드!!!\' 이후 포탑을 적절히 배치해 아트록스가 들어오기 까다로운 환경을 만드세요.', item: '리안드리의 고통을 첫 코어로 올려 지속적인 피해를 입히세요. 신발은 아트록스의 물리 피해를 줄이기 위해 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 아트록스의 (P)\'사신 태세\'와 (E)\'파멸의 돌진\' 회복을 억제하세요.' },
    '암베사': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치하여 암베사가 (P)\'용사냥개의 발걸음\'으로 쉽게 붙지 못하게 하세요. (W)\'마법공학 초소형 로켓\'을 사용해 거리를 유지하며 암베사의 체력을 미리 줄여두는 것이 좋아요. 암베사가 (Q)\'교활한 휩쓸기\'를 사용하며 다가올 때는 포탑의 사거리를 활용하며 거리를 벌리세요.', lv3: '암베사가 (E)\'찢어 가르기\'로 둔화를 걸고 돌진할 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시키는 것이 핵심이에요. 암베사가 (W)\'배척\'을 사용해 보호막을 얻는 동안에는 억지로 딜을 넣지 말고 기다리세요. 암베사가 스킬 사용 후 (P)\'용사냥개의 발걸음\'으로 움직일 때 (W)\'마법공학 초소형 로켓\'으로 적절히 응수하세요.', lv6: '암베사가 (R)\'공개 처형\'으로 순간 이동하여 제압을 시도할 때 위치를 조절해 대상이 되지 않도록 주의하세요. 제압 중에는 스킬을 쓸 수 없으니 (R)\'업그레이드!!!\'를 사용해 강화된 (E)\'CH-2 전자폭풍 수류탄\'으로 암베사의 진입을 미리 차단하세요. 암베사의 궁극기 이후에는 포탑을 강화하여 라인 주도권을 유지하며 관리하세요.', item: '판금 장화를 선택해 암베사의 기본 공격 피해를 줄이세요. 첫 코어로는 리안드리의 고통을 구매하여 포탑과 스킬로 지속적인 피해를 입히는 것이 좋아요.', spell: '점멸과 탈진을 추천해요. 암베사가 (P)\'용사냥개의 발걸음\'이나 스킬을 사용해 접근할 때 탈진을 사용해 입히는 피해량을 줄이세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'을 날려 맞은 적을 둔화시키고 끝에서 기절시키니 구체가 터지기 전에 옆으로 움직여 피하세요. (Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 상대가 접근하지 못하게 압박하며 초반 웨이브를 받아내세요. 포탑 주변에서 이동 속도가 증가하므로 이를 활용해 적절한 거리를 유지하세요.', lv3: '(Q)\'냉기 폭발\'에 맞은 상태에서 (E)\'동상\'을 맞으면 피해가 크게 늘어나니 구체에 맞았다면 즉시 뒤로 물러나세요. (W)\'결정화\' 벽이 세워지면 경로가 막히니 벽이 사라질 때까지 기다리거나 (W)\'마법공학 초소형 로켓\'으로 멀리서 견제하세요. 상대가 벽을 사용했다면 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시키고 포탑 화력을 쏟아부으세요.', lv6: '(R)\'얼음 폭풍\' 장판 위에서는 둔화 때문에 움직이기 어려우니 폭풍이 커지기 전에 범위 밖으로 벗어나세요. 애니비아가 접근하면 (R)\'업그레이드!!!\'를 쓴 (E)\'CH-2 전자폭풍 수류탄\'으로 기절을 노리세요. 애니비아가 (P)\'환생\'으로 알이 되면 포탑과 스킬로 알에 지속적인 피해를 입혀 빠르게 제거하세요.', item: '리안드리의 고통을 초반 코어로 선택해 고통 효과의 지속 피해와 체력을 챙기세요. 신발은 (Q)\'냉기 폭발\' 기절과 (R)\'얼음 폭풍\' 둔화 시간을 줄여주는 헤르메스의 발걸음이 적절해요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'의 기절이나 (R)\'얼음 폭풍\'의 둔화를 정화로 즉시 풀어 대응할 수 있어요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\'을 사용하여 회오리바람을 준비하니 (Q)\'H-28 G 진화형 포탑\'을 설치해 접근을 방해하세요. (W)\'마법공학 초소형 로켓\'으로 멀리서 견제하며 야스오의 (P)\'낭인의 길\' 보호막이 생기면 딜교환을 잠시 멈추세요. 포탑 근처에서 거리 조절을 하며 야스오가 미니언을 타고 들어오는 것을 경계해야 해요.', lv3: '야스오의 (W)\'바람 장막\'은 (W)\'마법공학 초소형 로켓\'과 같은 투사체를 막으니 벽이 사라진 뒤에 스킬을 사용하세요. 야스오가 (E)\'질풍검\'으로 진입할 때 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절을 맞히면 효과적으로 대응할 수 있어요. (Q)\'강철 폭풍\'의 회오리바람이 쌓이지 않도록 포탑을 활용해 거리를 유지하며 싸우세요.', lv6: '야스오가 (Q)\'강철 폭풍\'으로 공중에 띄우면 (R)\'최후의 숨결\'로 이어지니 회오리 중첩을 항상 조심하세요. (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'은 범위가 넓어져 야스오의 진입을 더 강력하게 저지할 수 있어요. 라인을 너무 밀어두면 야스오의 (E)\'질풍검\' 돌진에 노출될 수 있으니 주의하며 정글러의 위치를 확인하세요.', item: '루덴의 메아리를 첫 코어로 선택해 강력한 마법 피해를 입히세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오의 (P)\'낭인의 길\' 보호막이 사라진 순간 점화로 피해를 집중하면 킬각을 잡기 쉬워요.' },
    '오공': { lv1: '오공이 (Q)\'파쇄격\'을 사용해 접근할 때 (Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 대응하세요. 오공의 사거리가 길어지는 구간이 있으니 포탑의 도움을 받아 거리를 유지하며 견제해야 해요.', lv3: '오공이 (W)\'분신 전사\'로 투명해지면 분신과 본체를 잘 구분해야 해요. 오공이 (E)\'근두운 급습\'으로 돌진할 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시킨 뒤 포탑 화력을 집중하세요.', lv6: '오공이 (R)\'회전격\'을 사용해 적을 공중에 띄우면 스킬을 쓸 수 없으니 조심하세요. (R)\'업그레이드!!!\'를 사용하여 강화된 (E)\'CH-2 전자폭풍 수류탄\'으로 오공의 진입을 차단하며 싸우세요.', item: '판금 장화와 루덴의 메아리를 가세요. 오공의 물리 피해를 줄이고 강력한 마법 피해로 견제하기 위해서예요.', spell: '점멸과 탈진을 추천해요. 탈진으로 오공의 돌진 공격 피해량을 감소시키세요.' },
    '오로라': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 오로라가 쉽게 다가오지 못하게 하세요. 오로라가 (Q)\'이중 저주\'를 던지면 돌아오는 경로를 피해 옆으로 움직여야 해요. 포탑 사거리 안으로 들어오면 평타와 포탑 공격으로 압박하세요.', lv3: '오로라가 (E)\'마법의 문\'으로 둔화를 걸고 뒤로 도약하면 무리하게 쫓지 마세요. (W)\'장막 너머로\'를 써서 투명해졌을 때는 포탑 주변에서 대기하며 거리 조절을 하세요. 오로라가 진입하는 타이밍에 (E)\'CH-2 전자폭풍 수류탄\'을 정확히 던져 기절시킨 뒤 (W)\'마법공학 초소형 로켓\'으로 피해를 입히세요.', lv6: '오로라가 (R)\'세계의 경계\' 영역을 만들면 억지로 나가려다 둔화를 맞지 말고 포탑을 통해 버티세요. (R)\'업그레이드!!!\'를 사용해 강화 포탑을 배치하면 영역 안에서도 오로라의 접근을 효율적으로 막을 수 있어요. 영역 밖으로 나오는 오로라에게 (E)\'CH-2 전자폭풍 수류탄\'을 맞혀 킬각을 잡으세요.', item: '리안드리의 고통을 첫 코어로 가서 체력과 지속적인 피해를 확보하세요. 신발은 마법 저항력을 높이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'로 체력을 회복하므로 점화의 치유 감소 효과로 이를 억제해야 해요.' },
    '오른': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치하여 오른이 쉽게 접근하지 못하도록 하세요. (Q)\'용암 균열\'의 용암 기둥이 솟아오르는 위치를 확인하고 미리 옆으로 피하며 거리를 유지하세요. 포탑을 활용해 미니언을 압박하며 성장에 집중하세요.', lv3: '오른이 (E)\'화염 돌진\'으로 벽을 부딪쳐 띄우려 하면 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절을 노리세요. (W)\'불꽃 풀무질\'의 마지막 불꽃을 맞으면 이동 불가 효과가 길어지니 주의해야 해요. 포탑 근처에서 (W)\'마법공학 초소형 로켓\'으로 지속적인 피해를 입히세요.', lv6: '(R)\'업그레이드!!!\'로 강화된 (E)\'CH-2 전자폭풍 수류탄\'을 사용해 넓은 범위에 기절을 걸며 킬각을 잡으세요. (R)\'대장장이 신의 부름\'의 불의 정령이 지나가는 경로를 파악하고 정령에게 맞지 않게 조심하세요. 포탑을 이용해 라인을 밀어 넣고 정글러의 개입에 대비하세요.', item: '체력이 높은 오른에게 지속적인 피해를 주는 리안드리의 고통을 첫 코어로 가세요. 신발은 스킬을 더 자주 사용하여 압박하기 위해 명석함의 아이오니아 장화를 선택해요.', spell: '점멸과 순간이동을 추천해요. 오른은 체력이 많아 처치가 어려우니 순간이동으로 경험치 손실을 줄이세요.' },
    '올라프': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 올라프가 접근하는 경로를 막으세요. 올라프가 (Q)\'역류\'를 던져 둔화시키려 하면 최대한 거리를 벌리며 포탑 공격을 유도하세요. 올라프는 (P)\'광전사의 분노\'로 자신의 체력이 낮을수록 공격 속도와 생명력 흡수가 커지니 체력을 어중간하게 깎아둔 채 붙지 마세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'을 적중시켜 기절시킨 뒤 포탑의 충전 사격을 유도하세요. 올라프가 (W)\'버티기\'로 보호막을 얻고 달려들 때는 잠시 뒤로 물러나며 시간을 끄는 게 좋아요. (E)\'무모한 강타\'의 고정 피해를 맞지 않도록 주의하며 짧게 딜교환하고 빠지세요.', lv6: '(R)\'라그나로크\'가 켜진 올라프는 이동 불가 효과에 면역이라 (E)\'CH-2 전자폭풍 수류탄\'의 기절이 통하지 않으니 최대한 거리를 유지하세요. 궁극기 지속시간이 끝나면 (R)\'업그레이드!!!\'를 사용해 강화된 포탑으로 빠르게 피해를 입히세요. 라인을 깊게 밀면 올라프의 추격 속도가 빠르니 정글러의 개입을 고려해 조심하세요.', item: '판금 장화와 모렐로노미콘을 추천해요. 판금 장화로 기본 공격 피해를 줄이고 모렐로노미콘의 고통스러운 상처로 (P)\'광전사의 분노\' 회복력을 낮춰야 해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 올라프의 체력 회복을 억제하고 마무리 피해를 입히세요.' },
    '요네': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 요네가 접근할 때 피해를 입히세요. 요네가 (Q)\'필멸의 검\'을 두 번 맞히면 돌진해 띄우니, 직선 거리에서 벗어나며 거리를 조절하세요.', lv3: '요네가 (E)\'영혼해방\'을 사용해 진입하면 (E)\'CH-2 전자폭풍 수류탄\'을 발밑에 던져 기절시키세요. (W)\'영혼 가르기\'로 얻은 보호막이 사라질 때까지 (W)\'마법공학 초소형 로켓\'으로 견제하며 체력을 깎으세요. 요네의 (Q)\'필멸의 검\' 돌진 각을 예측해 수류탄으로 끊어내면 교환에서 앞서요.', lv6: '요네가 (R)\'운명봉인\'을 쓰기 전에 (R)\'업그레이드!!!\'를 사용해 강화된 수류탄으로 넓은 범위를 기절시켜 진입을 끊으세요. (Q)\'H-28 G 진화형 포탑\'을 요네의 진입 경로에 미리 깔아두고 정글러의 개입에 대비하세요. (R)\'운명봉인\'에 맞으면 공중으로 띄워져 스킬을 못 쓰니 요네가 일직선으로 파고들 수 있는 거리에 오래 서 있지 마세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력을 높이고 지속 피해를 입히세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요네가 (W)\'영혼 가르기\' 보호막으로 버티더라도 점화의 추가 피해로 빠르게 마무리할 수 있어요.' },
    '요릭': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 요릭이 (Q)\'최후의 의식\'으로 미니언을 쳐서 무덤을 만드는 것을 방해하세요. (W)\'마법공학 초소형 로켓\'으로 요릭을 견제하며 포탑의 충전량을 계속 유지하는 것이 중요해요. 요릭이 무덤을 쌓기 시작하면 포탑 근처에서 거리를 두며 대응하세요.', lv3: '요릭이 (E)\'애도의 안개\'를 던져 표식을 남기려 할 때 (E)\'CH-2 전자폭풍 수류탄\'으로 대응하며 거리를 벌리세요. 요릭이 (W)\'망자의 진\'으로 길을 막으면 포탑의 화력으로 벽을 부수거나 위치를 잘 잡아야 해요. (E)\'애도의 안개\'에 맞으면 방어력이 깎이고 둔화되니 뒤로 물러나며 (W)\'마법공학 초소형 로켓\'으로 피해를 입히세요.', lv6: '요릭이 (R)\'군도의 장송곡\'으로 안개 마녀를 소환하면 (R)\'업그레이드!!!\'를 사용해 강화된 (E)\'CH-2 전자폭풍 수류탄\'으로 대응하세요. 안개 마녀와 망령이 포탑을 빠르게 파괴할 수 있으니 라인을 관리하며 정글러의 개입을 요청해야 해요. 마녀가 소환된 뒤에는 요릭과 직접 싸우기보다 포탑의 화력을 활용해 거리를 유지하세요.', item: '리안드리의 고통을 첫 코어로 가서 요릭과 소환물들에게 지속적인 화상 피해를 입히세요. 신발은 요릭의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요릭의 (Q)\'최후의 의식\' 회복을 점화로 억제하며 킬각을 잡을 수 있어요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\' 태세로 다가오며 평타를 치면 강해요. (Q)\'H-28 G 진화형 포탑\'을 미리 설치하여 우디르가 접근하기 어렵게 만드세요. 우디르가 (E)\'불길 쇄도\'로 빠르게 다가오면 포탑 사거리 안에서 (W)\'마법공학 초소형 로켓\'으로 견제하며 거리를 유지하세요.', lv3: '우디르가 (W)\'강철 갑옷\'을 사용하여 보호막을 얻으면 딜교환을 잠시 멈추고 보호막이 사라지기를 기다리세요. 우디르가 (E)\'불길 쇄도\'로 기절을 노릴 때 (E)\'CH-2 전자폭풍 수류탄\'을 중앙에 맞춰 기절을 맞받아치는 것이 중요해요. (Q)\'H-28 G 진화형 포탑\'을 우디르의 이동 경로에 미리 설치하여 진입을 방해하세요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'을 켜고 다가오면 주변 둔화 때문에 포탑 근처에 머물기 어려우니 주의하세요. 우디르가 (E)\'불길 쇄도\'를 재사용하여 이동 불가 효과에 면역이 되면 (E)\'CH-2 전자폭풍 수류탄\'으로 제어하기 힘드니 거리를 벌리세요. (R)\'업그레이드!!!\'를 사용한 포탑으로 우디르의 진입을 막으며 라인을 관리하고 정글러를 부르세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 우디르의 물리 피해를 줄이고 지속적인 마법 피해를 입히기 위해서예요.', spell: '점멸과 점화를 추천해요. 우디르의 (W)\'강철 갑옷\' 회복을 억제하여 킬각을 잡기 위해서예요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸며 다가오니 (Q)\'H-28 G 진화형 포탑\'을 설치해서 거리를 유지하며 견제하세요. 첫 웨이브를 포탑으로 안전하게 받아내고 우르곳의 접근을 포탑의 공격으로 막아야 해요.', lv3: '우르곳이 (E)\'경멸\'로 돌진하면 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절을 노려 진입을 차단하세요. (W)\'심판의 원\'이 켜진 상태에서는 근접 교환이 위험하니 포탑과 (W)\'마법공학 초소형 로켓\'을 활용해 멀리서 딜교환을 하세요.', lv6: '(R)\'불사의 공포\' 섬광탄에 맞은 뒤 체력이 낮아지면 제압을 당해 처형될 수 있으니 섬광탄을 맞지 않도록 위치를 항상 신경 써서 피해야 해요. (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 우르곳의 진입을 광범위하게 저지하며 라인을 압박하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 우르곳을 지속적으로 압박하세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳이 체력이 낮은 대상을 처형하기 전에 점화로 마무리 피해를 더해 싸움을 끝내세요.' },
    '워윅': { lv1: '1~2레벨 구간에는 (Q)\'H-28 G 진화형 포탑\'을 미리 설치해 워윅이 접근할 때 피해를 누적시키세요. (Q)\'야수의 송곳니\'는 대상을 지정해 도약하므로 미니언 뒤에 숨어도 막을 수 없으니 주의하세요. 워윅의 체력이 낮아지면 (P)\'끝없는 허기\'로 빠르게 회복하니 체력을 조금씩 깎기보다 한 번에 쏟아부으세요.', lv3: '(W)\'마법공학 초소형 로켓\'으로 원거리에서 견제하며 체력을 낮게 유지하세요. 워윅이 (E)\'원시의 포효\'를 사용해 받는 피해를 줄일 때는 스킬을 아끼고, 포효가 끝나는 시점에 (E)\'CH-2 전자폭풍 수류탄\'으로 기절시켜 포탑 딜을 넣으세요. 내 체력이 절반 아래로 내려가면 (W)\'피의 사냥\' 때문에 워윅의 이동 속도가 매우 빨라지니 거리를 더 넓게 벌리세요.', lv6: '(R)\'무한의 구속\'은 도약해 제압하므로 정글러가 근처에 있을 때는 라인을 당겨서 안전하게 계세요. 제압 중에는 스킬을 쓸 수 없으니 워윅이 도약하기 전에 (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 기절시켜 진입을 끊으세요. 포탑 구역 안에서 싸우며 워윅이 (R)\'무한의 구속\'으로 물기 전에 최대한 거리를 벌리는 것이 중요해요.', item: '리안드리의 고통을 첫 코어로 삼아 체력이 높은 워윅에게 지속 피해를 입히고 망각의 구를 섞어 회복력을 낮추세요. 신발은 워윅의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 워윅의 (P)\'끝없는 허기\'와 (Q)\'야수의 송곳니\' 회복력을 억제해야 해요.' },
    '이렐리아': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 이렐리아가 (Q)\'칼날 쇄도\'로 미니언을 타고 들어오는 것을 견제하세요. 포탑 근처에서 이동 속도를 얻으며 거리를 유지하고, 상대가 무리하게 진입하면 평타로 대응하세요. 미니언 체력이 낮은 쪽에 서 있으면 상대의 접근이 빨라지니 위치를 조심하세요.', lv3: '(E)\'쌍검협무\'의 두 칼날이 만나는 경로를 피해서 기절과 표식을 허용하지 마세요. 상대가 (Q)\'칼날 쇄도\'로 진입할 때 (E)\'CH-2 전자폭풍 수류탄\'을 발밑에 던져 기절시키면 후속 딜교환을 막을 수 있어요. (W)\'저항의 춤\' 충전 중에는 마법 피해가 감소하니 충전이 끝난 후에 (W)\'마법공학 초소형 로켓\'을 맞히세요.', lv6: '(R)\'선봉진격검\'의 칼날 결계에 닿으면 둔화되니 빠르게 범위를 벗어나세요. 상대가 (Q)\'칼날 쇄도\'로 들어오는 타이밍에 (R)\'업그레이드!!!\'를 사용해 강화된 수류탄으로 기절시키면 안전하게 대응할 수 있어요. 라인을 당겨 (Q)\'H-28 G 진화형 포탑\' 화력으로 상대를 압박하며 정글의 개입을 기다리세요.', item: '리안드리의 고통과 판금 장화를 추천해요. 리안드리의 고통은 체력을 제공하고 지속 피해를 입히며, 판금 장화는 이렐리아의 기본 공격 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'칼날 쇄도\'의 체력 회복 효과를 감소시켜 상대의 유지력을 낮출 수 있어요.' },
    '일라오이': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 배치해 일라오이가 다가오기 전에 멀리서 피해를 입히세요. 일라오이가 (P)\'고대신의 예언자\'로 생성한 촉수 근처에는 가지 않도록 위치를 잡는 것이 중요해요. 1~2레벨에는 일라오이가 (Q)\'촉수 강타\'로 압박하기 전에 포탑의 화력을 활용해 라인을 관리하세요.', lv3: '일라오이가 (W)\'혹독한 가르침\'으로 돌진할 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절을 시키면 딜교환을 이끌어낼 수 있어요. (E)\'영혼의 시험\'에 맞아 영혼이 분리되면 일라오이가 영혼을 때릴 때 피해 일부가 나에게 들어오고, 영혼에서 너무 멀어지면 숙주가 되어 촉수를 불러오니 처음부터 이 스킬을 피하는 데 집중하세요. 포탑을 활용해 일라오이가 촉수를 이용해 반격하기 어렵게 만드세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 사용하면 많은 촉수가 소환되니 근처에서 교전하지 말고 거리를 벌리세요. (R)\'업그레이드!!!\'를 사용하여 (E)\'CH-2 전자폭풍 수류탄\'을 강화하면 일라오이의 접근을 더 효과적으로 차단할 수 있어요. 일라오이가 궁극기를 쓴 뒤에는 촉수가 사라질 때까지 라인을 당기며 정글러의 도움을 기다리세요.', item: '첫 코어 아이템으로 주문력과 마나를 제공하는 루덴의 메아리를 올리세요. 신발은 일라오이의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. 일라오이가 (W)\'혹독한 가르침\'이나 (R)\'믿음의 도약\'으로 들어올 때 탈진을 사용하면 피해량을 줄일 수 있어요.' },
    '자크': { lv1: '1~2레벨에는 (Q)\'H-28 G 진화형 포탑\'을 설치하여 자크의 접근을 억제하며 (W)\'마법공학 초소형 로켓\'으로 견제하세요. 자크가 (Q)\'탄성 주먹\'을 사용해 거리를 좁히려고 하면 포탑의 화력을 활용해 거리를 유지해야 해요. 자크가 조각을 모으기 전에 포탑으로 압박하며 미니언을 관리하세요.', lv3: '자크가 (E)\'새총 발사\'를 사용하며 몸을 늘릴 때 옆으로 움직여 공중으로 뜨는 것을 피하세요. 자크가 (Q)\'탄성 주먹\'으로 붙잡고 들어오려 하면 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시키거나 둔화시켜 거리를 벌려야 해요. 근처에서 (W)\'불안정 물질\'이 터지지 않도록 포탑이 설치된 구역 안에서 거리를 유지하세요.', lv6: '(R)\'업그레이드!!!\'를 사용한 강화된 (Q)\'H-28 G 진화형 포탑\'으로 자크의 체력을 빠르게 깎아 킬각을 잡으세요. 자크가 (R)\'바운스!\'를 사용해 공중으로 띄우면 스킬을 사용할 수 없으니 주의해야 해요. 자크가 (P)\'세포 분열\'로 살아남지 못하도록 포탑과 함께 폭발적인 피해를 입혀 한 번에 처치하세요.', item: '헤르메스의 발걸음과 루덴의 메아리를 가세요. 자크의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 가고, 강력한 견제를 위해 루덴의 메아리를 선택해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소로 자크의 회복을 줄이세요.' },
    '자헨': { lv1: '자헨은 (P)\'전쟁 단련\' 중첩을 쌓을수록 강해지니 최대한 멀리서 거리를 유지하세요. (Q)\'H-28 G 진화형 포탑\'을 설치해 자헨이 다가오는 길목을 차단하고 (W)\'마법공학 초소형 로켓\'으로 견제하세요. 1~2레벨에는 무리하게 맞붙기보다 포탑의 화력을 활용해 대응하는 것이 좋아요.', lv3: '자헨이 (W)\'공포의 귀환\'으로 끌어당기려 하면 옆으로 비켜서서 스킬을 피하세요. 자헨이 (E)\'찬란한 쇄도\'로 진입할 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시키면 딜교환을 성공할 수 있어요. (Q)\'다르킨의 글레이브\' 재사용으로 공중에 뜨지 않도록 주의하며 포탑 주변에서 싸우세요.', lv6: '자헨이 (R)\'단호한 판결\'로 공중에 떠오르면 착지 지점을 확인하고 범위 밖으로 벗어나세요. (R)\'업그레이드!!!\'를 사용해 강화된 수류탄으로 자헨의 진입을 억제하며 포탑 화력을 집중하세요. 자헨이 (R)\'단호한 판결\'로 체력을 회복하기 전에 (W)\'마법공학 초소형 로켓\'으로 빠르게 피해를 누적시켜야 해요.', item: '판금 장화와 리안드리의 고통을 선택하세요. 판금 장화는 자헨의 기본 공격 피해를 줄여주며 리안드리의 고통은 지속적인 마법 피해를 입히기에 좋아요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하니 점화로 치유 감소 효과를 보아야 해요.' },
    '잭스': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 배치해서 잭스가 미니언을 먹으러 올 때마다 피해를 주세요. (Q)\'도약 공격\'으로 순식간에 거리를 좁힐 수 있으니 항상 사거리 밖에서 움직이세요. (P)\'가차없는 맹공\'으로 공격 속도가 오르기 전에 짧게 딜교환하고 빠지세요.', lv3: '(E)\'반격\'을 켠 잭스는 기본 공격을 회피하고 끝날 때 주변을 기절시키니 포탑 사격을 몰아주지 말고 거리를 벌리세요. (E)\'반격\'이 끝나는 타이밍에 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시키면 진입을 효과적으로 끊을 수 있어요. (W)\'마법공학 초소형 로켓\'으로 멀리서 체력을 깎아 잭스가 쉽게 들어오지 못하게 하세요.', lv6: '(R)\'업그레이드!!!\'를 사용해 강화된 포탑을 설치하면 잭스가 진입할 때 강력한 피해와 둔화를 줄 수 있어요. (R)\'무기의 달인\'을 쓴 잭스는 방어력과 마법 저항력이 상승하므로 정면 승부는 피하고 거리 조절에 집중하세요. 라인을 계속 밀어 넣고 (Q)\'H-28 G 진화형 포탑\'을 촘촘히 배치해 잭스가 들어오기 힘든 구도를 만드세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 잭스에게 지속적인 피해를 입히세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화의 마무리 피해를 더해 잭스의 체력을 확실하게 깎으세요.' },
    '제이스': { lv1: '제이스가 캐논 형태에서 (Q)\'전격 폭발\'로 멀리서 견제하니 (Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 구역을 확보하세요. (P)\'마법공학 전문가\' 효과를 활용해 제이스의 (Q)\'전격 폭발\' 궤적에서 빠르게 벗어나며 거리를 조절하세요. 제이스가 해머로 (Q)\'하늘로!\'를 쓰며 접근할 때는 설치한 포탑의 화력으로 대응하며 위치를 잡으세요.', lv3: '제이스가 (E)\'가속 관문\'을 통해 강화된 (Q)\'전격 폭발\'을 쏘면 그 직선 경로에서 즉시 벗어나세요. 제이스의 (E)\'천둥 강타\' 사용을 유도한 뒤 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰서 기절시키면 딜교환에서 이득을 보세요. (W)\'마법공학 초소형 로켓\'을 맞춰서 포탑이 빠르게 충전되도록 관리하며 압박하세요.', lv6: '(R)\'업그레이드!!!\'를 사용해 강화된 (E)\'CH-2 전자폭풍 수류탄\'의 넓은 기절 범위로 제이스의 진입을 막고 킬각을 잡으세요. 제이스가 (R)\'머큐리 캐논\'으로 변환해 첫 공격으로 방어력과 마법 저항력을 깎으려 할 때 포탑 뒤에서 조심하세요. 제이스가 (E)\'천둥 강타\'로 밀어내며 거리를 벌릴 수 있으니 라인을 당겨서 정글러의 도움을 받기 쉽게 만드세요.', item: '루덴의 메아리를 첫 코어로 선택해 주문력과 마나를 확보하고 원거리 견제력을 높이세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 제이스가 스킬을 쓰고 형태를 바꾸는 틈에 점화를 섞어 킬각을 잡으세요.' },
    '초가스': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 초가스가 다가오지 못하게 압박하세요. 초가스가 (Q)\'파열\'을 사용할 때 지면이 솟아오르는 표시를 확인하고 빠르게 벗어나 공중에 뜨지 않도록 주의하세요. 무리하게 붙지 말고 포탑의 공격을 활용해 지속적으로 피해를 입히세요.', lv3: '초가스가 (W)\'흉포한 울부짖음\'을 쓰면 침묵되어 스킬을 사용할 수 없으니 원뿔 범위 밖에서 대기하다가 사용 후에 진입하세요. (E)\'CH-2 전자폭풍 수류탄\'을 적중시켜 기절시키면 근처 포탑이 최대로 충전되어 큰 피해를 줄 수 있어요. (E)\'날카로운 가시\'의 둔화 효과가 정면에 적용되니 정면에서 오래 맞서지 마세요.', lv6: '체력이 낮을 때 (R)\'포식\'에 잡히면 즉사할 수 있으니 항상 일정 거리를 유지하세요. (R)\'업그레이드!!!\'를 사용해 강화된 포탑을 설치하면 다가오는 초가스를 둔화시키며 효과적으로 막아낼 수 있어요. 라인을 밀어 초가스가 (R)\'포식\'으로 미니언을 잡아 성장하는 기회를 줄이세요.', item: '체력이 많은 상대에게 효과적인 리안드리의 고통을 첫 코어로 선택하세요. 신발은 마법 저항력을 제공하고 (W)\'흉포한 울부짖음\'의 침묵 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'육식\'의 회복 효과를 줄여 킬각을 잡으세요.' },
    '카밀': { lv1: '카밀은 (Q)\'정확성 프로토콜\'로 이동 속도를 높이며 빠르게 다가와 평타를 쳐요. (Q)\'H-28 G 진화형 포탑\'을 미리 설치해 접근을 방해하고 거리 조절을 하세요. (P)\'적응형 방어 체계\'로 생성되는 보호막이 있을 때는 딜교환을 피하고 보호막이 사라진 뒤에 공격하세요.', lv3: '(E)\'갈고리 발사\'로 진입하는 카밀의 착지 지점에 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시키세요. 카밀의 (W)\'전술적 휩쓸기\' 바깥쪽에 맞으면 둔화되고 카밀이 체력을 회복하니 원뿔 범위에서 완전히 벗어나세요. (W)\'마법공학 초소형 로켓\'으로 계속 체력을 깎아 (E)\'갈고리 발사\' 진입 의지를 꺾어놓으세요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 탈출이 불가능하니 카밀이 궁극기를 쓰기 전에 (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 먼저 끊어내세요. 카밀은 (E)\'갈고리 발사\'로 벽을 넘어 기습하므로 라인 관리 시 벽 근처에서 너무 오래 머물지 마세요. 포탑을 넓게 배치해 정글러의 진입 경로를 미리 파악하고 대응하세요.', item: '리안드리의 고통과 판금 장화를 추천해요. 체력이 높은 카밀에게 지속 피해를 입히고 판금 장화로 (Q)\'정확성 프로토콜\'의 평타 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. (W)\'전술적 휩쓸기\'를 통한 카밀의 체력 회복을 방해하고 킬각을 잡기 좋아요.' },
    '카사딘': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 카사딘의 접근을 막으세요. (W)\'마법공학 초소형 로켓\'으로 멀리서 견제하며 포탑 충전을 도와야 해요. 카사딘이 (Q)\'무의 구체\'로 보호막을 얻기 전에 지속적인 피해를 입히세요.', lv3: '카사딘이 (Q)\'무의 구체\'를 사용하여 보호막을 얻으려 할 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰서 기절시키는 것이 중요해요. 상대의 (E)\'힘의 파동\'을 먼저 피하면서 포탑 범위 안에서 싸워야 해요. (W)\'마법공학 초소형 로켓\'을 계속 맞춰서 포탑 충전 속도를 높여야 해요.', lv6: '카사딘이 (R)\'균열 이동\'을 여러 번 사용하여 순식간에 거리를 좁히니 주의해야 해요. (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 넓은 범위의 기절을 노려보세요. 카사딘이 도망가기 쉬우므로 라인을 관리하며 정글러의 도움을 기다려야 해요.', item: '루덴의 메아리를 첫 코어 아이템으로 선택해서 스킬 견제력을 높이세요. 신발은 카사딘의 마법 피해에 대비해 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 마무리 피해로 도망가는 카사딘을 처치하세요.' },
    '카시오페아': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치하고 그 주변에서 짧은 딜교환을 유도하세요. 카시오페아가 (Q)\'맹독 폭발\'로 견제하려고 하면 포탑의 사거리 안으로 유인해서 피해를 입히세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'을 정확히 맞춰 카시오페아를 기절시키고 (W)\'마법공학 초소형 로켓\'으로 추가 피해를 입히세요. (W)\'독기의 늪\' 위에 서 있으면 둔화되어 공격받기 쉬우니 빠르게 범위를 벗어나세요.', lv6: '(R)\'업그레이드!!!\'를 사용해 강화된 포탑을 배치하여 압박하고 킬각을 잡으세요. 카시오페아가 (R)\'석화의 응시\'를 사용할 때는 즉시 뒤를 돌아 기절을 피하고 둔화 상태에서 거리 조절을 하세요.', item: '헤르메스의 발걸음과 리안드리의 고통을 선택해요. 마법 저항력과 강인함으로 군중 제어 지속시간을 줄이고 지속적인 마법 피해를 입히기 위해서예요.', spell: '점멸과 점화예요. (E)\'쌍독니\'를 통한 체력 회복을 억제하고 확실하게 적을 처치하기 위해서예요.' },
    '케넨': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 케넨이 함부로 다가오지 못하게 하세요. 케넨이 (Q)\'천둥의 표창\'으로 견제하며 (P)\'폭풍의 표식\'을 쌓으려 하니, 표식이 세 번 쌓여 기절하기 전에 적당히 거리를 벌리세요.', lv3: '케넨이 (E)\'번개 질주\'로 빠르게 진입할 때 (E)\'CH-2 전자폭풍 수류탄\'을 발밑에 던져 기절시키세요. 기절한 틈에 (W)\'마법공학 초소형 로켓\'을 맞춰 포탑을 충전시키면 짧은 교환에서도 앞설 수 있어요. (W)\'전류 방출\'로 표식이 빠르게 쌓이기 전에 거리 조절을 하며 딜교환하세요.', lv6: '(R)\'업그레이드!!!\'를 사용한 뒤 (E)\'CH-2 전자폭풍 수류탄\'을 강화해 넓은 범위에 기절을 걸면 케넨의 진입을 효과적으로 끊을 수 있어요. 케넨이 (R)\'날카로운 소용돌이\'를 켜면 기절이 매우 빠르게 쌓이니 즉시 뒤로 물러나세요. 포탑 주변에서 (Q)\'H-28 G 진화형 포탑\'의 화력을 활용해 정글러와 함께 킬각을 잡으세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력을 보충하고 지속 피해를 입히세요. 신발은 마법 저항력을 높이고 기절 지속시간을 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 정화를 추천해요. 케넨의 (P)\'폭풍의 표식\'으로 인한 기절을 정화로 즉시 풀고 빠져나갈 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'으로 레벨이 오를수록 사거리와 화력이 강해지지만 초반에는 매우 약한 구간이에요. (Q)\'H-28 G 진화형 포탑\'을 설치하여 케일이 미니언을 먹을 때마다 견제하며 압박하세요. 케일의 (Q)\'광휘의 일격\' 사거리 안으로 무리하게 들어가지 않도록 주의하며 포탑의 도움을 받아 거리를 유지하세요.', lv3: '케일의 (Q)\'광휘의 일격\'을 피하면서 (E)\'CH-2 전자폭풍 수류탄\'을 적중시켜 기절을 시키는 것이 핵심이에요. 케일이 (E)\'화염주문검\'을 사용하여 잃은 체력에 비례한 피해를 입히기 전에 포탑과 함께 먼저 압박해야 해요. (W)\'마법공학 초소형 로켓\'을 케일에 맞춰 쏘면 근처 포탑이 빠르게 충전되어 더 강력한 피해를 줄 수 있어요.', lv6: '케일이 (R)\'신성한 심판\'을 사용하면 무적 상태가 되어 모든 피해를 받지 않으므로 스킬을 함부로 사용하지 마세요. 케일의 궁극기가 빠진 것을 확인한 뒤 (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 기절을 걸고 킬각을 잡으세요. 케일의 사거리가 길어지기 전에 라인을 빠르게 밀어 정글러의 개입을 유도하는 것이 좋아요.', item: '마법 피해를 줄이는 헤르메스의 발걸음을 신발로 선택하세요. 첫 코어 아이템으로는 주문력을 높여주는 루덴의 메아리를 추천해요.', spell: '점멸과 점화를 추천해요. 케일이 (W)\'천상의 축복\'으로 체력을 회복하며 버티지 못하도록 점화로 마무리하세요.' },
    '코그모': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치하여 코그모가 다가오기 힘든 구역을 만드세요. 코그모의 (Q)\'부식성 침\'은 미니언 뒤에 숨어 피하며 파밍에 집중해요. 포탑 주변에서 (P)\'마법공학 전문가\'의 이동 속도 증가를 활용해 거리 조절을 하세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'을 맞춰 코그모를 기절시키거나 둔화시키며 딜교환을 하세요. 코그모가 (W)\'생체마법 폭격\'으로 사거리를 늘렸다면 무리하게 들어가지 말고 포탑을 활용해요. (W)\'마법공학 초소형 로켓\'으로 적중시켜 포탑을 빠르게 충전하세요.', lv6: '(R)\'업그레이드!!!\'를 사용해 강화된 기술로 코그모를 압박하세요. 코그모의 (R)\'살아있는 곡사포\' 사거리와 피해를 조심하며 라인을 관리해요. 정글러가 올 때를 대비해 포탑을 적절한 위치에 미리 배치해요.', item: '루덴의 메아리를 첫 코어로 가서 스킬 피해를 높이세요. 신발은 코그모의 마법 피해에 대비해 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 선택하세요. 점멸로 위치를 옮겨 대응하고 점화로 체력이 낮은 코그모를 마무리해요.' },
    '코르키': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 설치하여 코르키의 접근을 막으세요. 코르키가 (Q)\'인광탄\'을 던지면 포탑 근처에서 (W)\'마법공학 초소형 로켓\'으로 응수하며 포탑을 충전시켜요. 초반에는 포탑의 화력을 활용해 거리를 유지하며 압박하는 것이 좋아요.', lv3: '코르키가 (W)\'발키리\'로 들어올 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시키세요. 코르키의 (E)\'개틀링 건\' 사거리에 들어가지 않도록 주의하며 포탑과 로켓으로 딜교환을 해요. 코르키의 스킬을 피하며 포탑 충전 상태를 계속 확인하세요.', lv6: '(R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 넓은 범위를 기절시켜 킬각을 노리세요. 코르키의 (R)\'미사일 폭격\'은 처음 맞힌 적 주변에 폭발 피해를 주니 날아오는 궤적에서 옆으로 비켜서세요. 포탑으로 라인을 밀어넣고 정글러의 위치를 파악하며 플레이하세요.', item: '판금 장화와 루덴의 메아리를 선택해요. 판금 장화로 (P)\'마법공학 탄약\'이 실린 코르키의 기본 공격 피해를 줄이고 루덴의 메아리로 강력한 마법 피해를 입혀요.', spell: '점멸과 점화를 추천해요. 점멸로 위치를 조절하고 점화로 마무리 피해를 더하세요.' },
    '퀸': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 퀸이 쉽게 들어오지 못하게 구역을 만드세요. 퀸이 (P)\'매사냥\' 표식을 남기고 접근하면 평타 교환을 피하고 포탑 주변에서 (P)\'마법공학 전문가\' 이동 속도 증가 효과를 활용해 거리 조절을 하세요. (Q)\'실명 공격\'에 맞으면 시야가 좁아지니 포탑 화력을 믿고 침착하게 뒤로 물러나세요.', lv3: '퀸이 (E)\'공중제비\'로 돌진해 들어오는 순간에 맞춰 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시키세요. 퀸이 다시 물러난 뒤에는 (W)\'마법공학 초소형 로켓\'을 적중시켜 포탑을 빠르게 충전하고 지속적으로 체력을 깎으세요. (E)\'공중제비\'의 둔화 효과에 걸렸을 때 억지로 쫓아가기보다 포탑의 사거리 안에서 버티는 것이 좋아요.', lv6: '퀸이 (R)\'후방 지원\'으로 빠르게 접근해 강습할 때 (R)\'업그레이드!!!\'를 사용해 강화된 수류탄으로 넓은 범위를 기절시키세요. 퀸이 날아다니며 라인을 비우면 빠르게 웨이브를 밀어 포탑에 압박을 주고 정글러의 개입을 기다리세요. (E)\'공중제비\'로 거리를 벌리려는 퀸의 움직임을 예측해 (Q)\'H-28 G 진화형 포탑\'을 미리 배치해 두세요.', item: '판금 장화와 루덴의 메아리를 추천해요. 판금 장화로 퀸의 기본 공격 피해를 줄이고 루덴의 메아리로 강력한 마법 피해를 입히세요.', spell: '점멸과 순간이동을 추천해요. 퀸의 높은 기동성에 대응해 빠르게 합류하거나 복귀하는 것이 중요해요.' },
    '크산테': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 크산테가 다가오지 못하게 하세요. 크산테가 (Q)\'엔토포 타격\'으로 둔화를 걸며 접근하려 하면 거리를 유지하며 견제해요. 포탑 주변에서 (P)\'마법공학 전문가\'의 이동 속도 증가 효과를 활용해 공격 범위를 벗어나세요.', lv3: '크산테가 (W)\'길을 여는 자\'를 충전하면 저지 불가 상태라 기절로 막을 수 없으니 충전 모습이 보이면 즉시 옆으로 피하세요. (E)\'발놀림\'으로 빠르게 붙으려는 크산테의 발밑에 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시킨 뒤 거리를 벌리세요. 이후 (W)\'마법공학 초소형 로켓\'을 적중시켜 포탑을 충전하며 체력을 깎으세요.', lv6: '(R)\'총공세\'는 적을 벽 너머로 밀어내며 진입하니 벽 근처에 서지 않도록 주의하세요. 크산테가 총공세 상태가 되어 방어력이 낮아지면 (R)\'업그레이드!!!\'를 사용해 강화된 포탑을 깔아 강력한 피해를 입히세요. 라인을 밀어 넣은 상태에서 (Q)\'H-28 G 진화형 포탑\'의 화력으로 정글 개입을 억제하며 압박하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 크산테에게 지속적인 마법 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 크산테는 체력이 많아 처치가 어려우니 순간이동으로 라인 손실을 최소화하세요.' },
    '클레드': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해 스칼의 체력을 깎으며 견제하세요. (Q)\'덫날리기\'에 맞은 뒤 클레드와 근거리를 유지하면 끌려가며 추가 피해를 입으니 즉시 거리부터 벌려야 해요.', lv3: '클레드가 (E)\'이랴!\'로 돌진해 들어오는 경로에 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시키세요. (W)\'버럭버럭\'이 켜진 동안은 공격 속도가 매우 빨라지니 평타 교환을 피하고 (W)\'마법공학 초소형 로켓\'으로 멀리서 견제하세요.', lv6: '(R)\'돌겨어어억!!!\'은 보호막을 쓰고 일직선으로 돌진하니 경로에서 빠르게 벗어나세요. (R)\'업그레이드!!!\' 사용 후 강화된 수류탄으로 진입하는 클레드를 기절시켜 흐름을 끊으세요. 스칼에서 내린 클레드는 챔피언에 대한 피해량이 줄어드니 이때를 노려 빠르게 정리하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 스칼에게 지속 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드는 대신 피해를 받아줄 스칼이 없으므로 점화로 빠르게 마무리하기 편해요.' },
    '탐켄치': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 탐 켄치가 다가오지 못하게 하세요. 탐 켄치가 평타로 (P)\'절대 미각\' 중첩을 쌓으려 하면 뒤로 물러나며 (W)\'마법공학 초소형 로켓\'으로 견제하세요. 초반에는 포탑 근처에서 싸우며 거리를 유지하는 것이 중요해요.', lv3: '탐 켄치가 (Q)\'혀 채찍\'을 쓰며 다가오면 (E)\'CH-2 전자폭풍 수류탄\'을 던져 기절시키거나 둔화시켜 거리를 벌리세요. 탐 켄치의 (W)\'심연 잠수\'가 사용되어 공중으로 뜨는 것을 조심하며 포탑 화력으로 압박하세요. (P)\'절대 미각\' 중첩이 쌓이지 않도록 짧게 딜교환하고 빠지는 것이 좋아요.', lv6: '(R)\'업그레이드!!!\'를 사용한 강화된 포탑으로 탐 켄치를 강하게 압박하며 라인을 밀어넣으세요. 탐 켄치가 (R)\'집어삼키기\'를 사용할 수 있는 중첩 상태라면 포탑 밖으로 빠르게 이동해야 해요. 정글러가 오더라도 포탑 근처에서 (E)\'CH-2 전자폭풍 수류탄\'으로 대응하며 버티세요.', item: '체력이 높은 탐 켄치에게 지속 피해를 입히기 위해 리안드리의 고통을 첫 코어로 가세요. 신발은 탐 켄치의 마법 피해에 대비한 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 체력 회복 효과를 줄이며 킬을 노리세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 흡수하며 다가오니 (Q)\'H-28 G 진화형 포탑\'을 먼저 설치해 거리를 두세요. (W)\'마법공학 초소형 로켓\'으로 멀리서 견제하며 트런들이 붙지 못하게 관리해야 해요.', lv3: '트런들이 (W)\'얼음 왕국\'을 사용하면 영역 안에서 공격 속도가 빨라지고 치유량이 늘어나니 영역 밖으로 벗어나세요. 트런들이 (Q)\'깨물기\'를 사용하며 다가올 때 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절시키면 포탑이 즉시 충전되어 교환을 이끌어내기 좋아요.', lv6: '트런들이 (R)\'진압\'을 사용해 체력과 방어력을 훔치면 즉시 거리를 벌려야 해요. (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 광범위하게 기절을 걸고 (Q)\'H-28 G 진화형 포탑\'을 깔아 압박하세요. 트런들은 (P)\'헌납\'으로 근처 유닛이 쓰러질 때 회복하니 미니언이 많은 곳에서는 조심하세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화는 트런들의 기본 공격 피해를 줄여주고 리안드리의 고통은 지속적인 마법 피해를 입히기 좋아요.', spell: '점멸과 점화를 추천해요. 점화는 트런들이 (P)\'헌납\'으로 체력을 회복하는 것을 억제하기 좋아요.' },
    '트린다미어': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치해서 트린다미어가 들어오기 힘든 구역을 만드세요. 트린다미어가 (P)\'격노\'를 쌓으며 다가오면 포탑 근처에서 이동 속도를 높여 거리를 유지하세요. 첫 웨이브부터 무리하게 딜교환하지 말고 짧게 견제하며 체력을 보존하세요.', lv3: '트린다미어가 (E)\'회전 베기\'로 빠르게 진입할 때 (E)\'CH-2 전자폭풍 수류탄\'을 발밑에 던져 기절시키세요. (W)\'조롱의 외침\'을 맞고 등을 돌리면 둔화되니 주의하며 (W)\'마법공학 초소형 로켓\'으로 지속적인 피해를 입히세요. 기절시킨 직후 포탑의 충전 사격이 터지도록 유도해 짧고 강하게 공격하고 빠지세요.', lv6: '(R)\'불사의 분노\'가 켜지면 죽지 않으니 무리하지 말고 거리를 벌리며 버티세요. 궁극기 지속시간이 끝나갈 때 (R)\'업그레이드!!!\'를 사용해 강화된 스킬로 압박하며 마무리하세요. (Q)\'피의 갈망\'으로 회복하기 전에 빠르게 피해를 입히고 정글러의 개입을 요청하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력을 높이고 지속 피해로 압박하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복하는 것을 점화의 치유 감소로 방해하세요.' },
    '티모': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치하여 티모가 함부로 들어오지 못하게 하세요. 티모가 (E)\'맹독 다트\'로 독을 묻히며 압박하므로 포탑 주변에서 (P)\'마법공학 전문가\'의 이동 속도를 활용하세요. (Q)\'실명 다트\'에 맞으면 실명 상태가 되니 그동안은 평타 교환을 하지 말고 거리를 조절하세요.', lv3: '티모의 (Q)\'실명 다트\'가 빠진 직후에 (E)\'CH-2 전자폭풍 수류탄\'을 맞춰 기절을 유도하세요. 티모가 (W)\'신속한 이동\'으로 도망가려 하면 (W)\'마법공학 초소형 로켓\'을 맞춰 포탑을 충전시키세요. 실명 상태가 되지 않도록 주의하며 포탑과 함께 티모를 압박하세요.', lv6: '티모가 설치한 (R)\'유독성 함정\'은 밟으면 둔화와 피해를 입히니 수풀 근처를 조심하세요. (R)\'업그레이드!!!\'를 (E)\'CH-2 전자폭풍 수류탄\'에 사용하여 넓은 범위의 기절을 맞히면 킬각을 잡을 수 있어요. 티모가 (R)\'유독성 함정\'을 깔고 도망가면 (W)\'마법공학 초소형 로켓\'으로 포탑을 빠르게 채우며 압박하세요.', item: '루덴의 메아리를 첫 코어로 선택해 스킬 견제력을 높이세요. 신발은 티모의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 티모를 (E)\'CH-2 전자폭풍 수류탄\'으로 기절시킨 뒤 점화로 체력을 빠르게 깎으세요.' },
    '판테온': { lv1: '(Q)\'H-28 G 진화형 포탑\'을 미리 설치하여 판테온이 다가오기 어렵게 만들어요. 판테온이 (Q)\'혜성의 창\'으로 견제할 때 (W)\'마법공학 초소형 로켓\'을 맞히며 거리를 유지하세요. 판테온의 (P)\'필멸자의 의지\'가 쌓여 강화된 공격이 나오기 전까지는 거리를 두는 게 좋아요.', lv3: '판테온이 (W)\'방호의 도약\'으로 진입하면 (E)\'CH-2 전자폭풍 수류탄\'을 사용하여 기절시키거나 둔화시켜야 해요. 판테온이 (E)\'방패 돌격\'을 켜면 지정한 방향의 피해를 막으니 정면으로 스킬을 쏟지 말고 끝나는 시점을 기다리세요. (W)\'방호의 도약\'이 빠진 뒤에 포탑과 함께 공격을 이어가세요.', lv6: '판테온이 (R)\'거대 유성\'을 써서 사라지면 다른 라인 합류 신호이니 즉시 맵을 확인하세요. 판테온이 진입하는 순간 (R)\'업그레이드!!!\'를 사용하여 강화된 (E)\'CH-2 전자폭풍 수류탄\'으로 대응하세요. 포탑 근처에서 (W)\'마법공학 초소형 로켓\'으로 체력을 깎아두면 킬각을 잡기 수월해요.', item: '루덴의 메아리를 첫 코어로 가서 마법 피해와 마나를 확보하세요. 신발은 판테온의 물리 피해를 줄이는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 판테온의 체력을 깎으며 초반 압박을 극대화하세요.' },
    '피들스틱': { lv1: '1~2레벨에는 (Q)\'H-28 G 진화형 포탑\'을 설치하며 라인을 관리해요. 피들스틱이 시야 밖에서 (Q)\'공포\'를 사용하지 못하도록 주변 시야를 확보하며 (W)\'마법공학 초소형 로켓\'으로 거리를 유지해요.', lv3: '3레벨 이후 피들스틱이 (W)\'풍작\'으로 체력을 회복하려 하면 (E)\'CH-2 전자폭풍 수류탄\'을 던져 대응해요. 피들스틱의 (E)\'수확\' 범위 중심에 있으면 침묵에 걸리니 주의하며 포탑의 화력을 활용해요.', lv6: '6레벨 이후 피들스틱이 (R)\'까마귀 폭풍\'으로 진입하면 (R)\'업그레이드!!!\'를 사용해 (E)\'CH-2 전자폭풍 수류탄\'의 범위를 넓혀 대응해요. 상대가 시야 밖에서 나타나는 것을 대비해 와드를 설치하고 정글러의 개입에 대비해 라인 높이를 조절해요.', item: '헤르메스의 발걸음과 루덴의 메아리를 선택해요. 피들스틱의 마법 피해를 줄이기 위해 신발을 고르고 강력한 마법 피해를 위해 코어 아이템을 갖춰요.', spell: '점멸과 점화를 추천해요. 점화는 피들스틱이 (W)\'풍작\'으로 체력을 회복하는 것을 억제하여 킬을 내는 데 도움을 줘요.' },
    '피오라': { lv1: '1~2레벨에는 (Q)\'H-28 G 진화형 포탑\'을 설치해 진입을 억제하고 (W)\'마법공학 초소형 로켓\'으로 피오라의 체력을 깎으세요. 피오라가 (Q)\'찌르기\'로 파고들 때 포탑의 화력을 이용해 거리를 벌리는 것이 중요해요. 포탑을 중심으로 라인을 관리하며 피오라가 무리하게 들어오지 못하게 하세요.', lv3: '피오라가 (W)\'응수\'를 사용하면 모든 공격과 이동 불가 효과를 막아내며 반대로 기절을 걸 수 있으니 주의하세요. (E)\'CH-2 전자폭풍 수류탄\'을 던지기 전에 피오라의 (W)\'응수\'가 빠졌는지 반드시 확인해야 해요. (W)\'마법공학 초소형 로켓\'을 활용해 포탑을 충전시키며 지속적으로 견제하세요.', lv6: '피오라가 (R)\'대결투\'를 사용하면 급소를 노리며 빠르게 움직이니 (R)\'업그레이드!!!\'를 사용한 (E)\'CH-2 전자폭풍 수류탄\'으로 넓은 범위의 기절을 노리세요. 급소를 맞히면 피오라가 체력을 회복하므로 포탑과 함께 화력을 집중해 빠르게 대처하세요. 라인을 밀어넣고 정글러와 함께 피오라의 움직임을 압박하세요.', item: '루덴의 메아리를 첫 코어로 가서 강력한 주문력과 마법 피해를 입히세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'로 체력을 회복할 때 점화로 그 효과를 억제하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_heimerdinger);
if (typeof module !== 'undefined') module.exports = top_heimerdinger;
